-- GENERATED by `wfj generate` from data/quest/quest-0093.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [93016] = { "簡単な歴史の授業", "修理したクリスタルについて情報を得るため、Shen'dralasにいるMordent Evenshadeと話してください。", "何の説明もせずに、次々と用事を頼んでしまったことをお許しください。これがどれほど怪しく見えたか、考えていませんでした。空がこれほど劇的な様子になった今となっては、なおさらでしょう。\n\nご質問には喜んでお答えします。", nil, nil, 0xd302b652, 0x5b6ead89, 0x2a2142fc, nil, nil, "...mm" },
  [93030] = { "嘆きの騎士", "Knight of Mourningと話し、彼のやり残したクエストについて詳しく聞いてください。", "私もかつては君と同じ騎士だった。光に仕える身だった。そして、死んだ。どうやら我々には、それだけの共通点があるようだ。\n\nだが君と違い、私は果たされぬ目的と、守られぬ誓いによってこの地に縛られている。聞いてくれるなら、私の探求……そして私の失敗について話そう。", nil, nil, 0xa9e3fad4, 0x8973b7c9, 0x7f0121b3, nil, nil, "...mm" },
  [93034] = { "Valley of Bones", "Gelkisとの評判を上げ、Gelkis Villageのはるか東にあるValley of Bones近くでNerlokhを探し出す。", "あなたが留守の間に、斥候の一人が村に戻ってきて、私の恐れていたことを裏付ける知らせをもたらしました。\n\nMagramが何かを企んでいます、{name}。良くないことです。\n\nはるか東のValley of Bonesは呪われた地で、足を踏み入れるcentaurはわずかで、生きて帰る者はさらに少ないのです。敵はそこで何か、邪悪な何かを見つけました。それが何なのかを突き止めなければなりません。\n\n南の入口にいる斥候のNerlokhを訪ねてください。ただ、Gelkisにさらに自分の力を示す必要があるかもしれません。", nil, nil, 0x1c23f49e, 0xc34a0910, 0xad8eaac4, nil, nil, "...mm" },
  [93035] = { "荒れ狂うRavager", "Gelkis Clanとの評判を維持し、Undead Ravagersを$N1体倒す。その後、Valley of Bonesの南の入口にいるNerlokhのもとへ戻る。", "前方をよろめき歩くアンデッドは遠くを見るまでもなく目に入るが、奴らに何か変わったところがあるのに気づいたか？\n\n奴らは4本ではなく、2本の脚で歩いている！このスケルトンどもは、倒れた我らの同胞ですらない。Magramは、Desolaceが我らの領土となるはるか以前に死んだ者たちの亡骸を汚しているに違いない。奴らがどうやってMother Theradrasに背を向け、何世紀もここで眠ってきた遺体を冒涜することを正当化したのか、想像もつかない。\n\nアンデッドを眠りにつかせてやってくれ、{name}。", nil, nil, 0x153e1e0b, 0x5480b72b, 0x3fc928fd, nil, nil, "...mm" },
  [93036] = { "教団への潜入", "Shen'dar VillageのSania Silverstreamと話してください。", "知っているかどうかは分からないが、あそこにいるSania SilverstreamはAl'Akethの「宣教師」だ。奴らは普通の宗教団体のふりをして、害のなさそうな使者をあちこちに送って信者を集めている。教団との直接の衝突を避けるために、これまではSaniaを大目に見てきたが、見せかけの平和がこれ以上長く続かないのは明らかだ。\n\n君はここに来たばかりで、ほとんどの者に顔を知られていない。だから、Saniaを利用して教団に近づき、奴らが村に対して何を企んでいるのか探れないか試してほしい。", nil, "ごきげんよう、子よ。私の名はSania Silverstream、Order of the Al'Akethの見習い祭司です。我らが君主、Windlord Al'Akirについてもっと知りたいですか？\n\nWindlordの食卓には、正しき者と悔い改めた者のための席がいつでもあるのです。", 0xbb1fd4b2, 0x82bd3020, 0x59a588f5, nil, 0x23ca2220, "...m." },
  [93037] = { "追放者をあぶり出す", "Gelkis Clanとの評判を維持し、Necromantic Garbを$N1着、Valley of Bonesの入口にいるNerlokhに届ける。", "あなたの到着を待つ間、アーチの間をもう少し奥まで覗いてみて、確かめてほしいことに気づいた。\n\n口に出すのも耐えられない。疑いが本当だと証明されるまでは。\n\n{name}、谷で様子をつかみながら、ほかより弱そうに見える死霊術師を何人か倒してくれ。奴らの儀式のgarbを慎重に剥ぎ取り、私のもとへ持ってきてほしい。私の頭と目が確かなのかどうか、知らねばならない。", nil, nil, 0x7c82b69a, 0xffce3927, 0x80ee307a, nil, nil, "...mm" },
  [93041] = { "真実と向き合う", "Gelkis Clanとの評判を維持し、Accursed SkullとGelkis Necromantic GarbをGelkis VillageのUthek the Wiseに届ける。", "この発見は我らの氏族にとって打撃だが、知るべき者だけにとどめておくのが最善だ。Uthekはここで起きていることを知っておくべき者の一人だ。彼女ならどう進めるべきか分かるだろう。\n\nこれを持って行って彼女に見せてくれ。念のため、死霊術そのものの証拠も持って行くべきだ。最近呪われたように見えるskullを探してくれ。奴らは巨人の骸骨のひとつの口の中にそれをため込んでいるのではないかと思う。", nil, nil, 0x8463c2a2, 0x5ff29d36, 0x49b8d0dc, nil, nil, "...mm" },
  [93044] = { "浄化の叫び", "Gelkisとの評判を維持し、Tears of TheradrasをGelkis VillageのUthek the Wiseのもとへ持ち帰る。", "Valley of BonesのNerlokhのもとへ戻るときは、手ぶらではない。\n\n我らの村の中心にある洞窟へ入り、Mularaを探せ。私の代わりにTears of Theradrasを求めるのだ。蓄えは少ないが、Magramのおぞましい死霊術に対する我らの最大の望みだ！\n\n私は儀式の準備をする。奴らの呪文を妨げる武器を作るのだ。", nil, nil, 0x0d21377b, 0xf97c47c3, 0x548749f1, nil, nil, "...mm" },
  [93045] = { "仮説を試す", "Gelkisとの評判を維持し、Accursed Skullにかけられた死霊術の呪いを解く。成功したら、Valley of Bones近くのNerlokhのもとへ報告に戻る。", "あなたが持ってきてくれた頭蓋骨を、あなたの帰りを待つ間に見つけたいくつかの骨の隣に置きました。すると即座に、病的な光が頭蓋骨から広がり、その古い骨を我が物にするのが見えたのです。死霊術の呼び声に抗うのがなぜこれほど難しいのか、今なら分かります。\n\nこの水晶を覚えていますか？これはdraenethystです。その可能性についてはほとんど知りませんが、Theradrasの力を導くことができると信じています。これを使えば、呪いを解くことができるかもしれません。\n\n儀式の場所は、村のすぐ東にある池のほとりにあります。", nil, nil, 0xdd0047fc, 0x79d5c999, 0x89f01149, nil, nil, "...mm" },
  [93058] = { "仲間を救う", "Gelkis氏族との評判を維持し、Valley of Bones内でGelkis Captivesを$N1人救出する。終わったら入口近くのNerlokhのもとへ戻る。", "丘のすぐ向こうで数人の死霊術師たちの間に短い戦いがあり、私はその隙に中をよく見てきた。\n\n{name}、最近の我々の損失のすべてが離反者だったわけではない。谷のさらに奥でGelkisが捕らえられているのだ！巨体のMagramの荒くれ者が私の方へ突進してきたので、彼らの状況を調べることはできなかった。奴がすぐに興味を失ってくれたのは幸運だったと思う。\n\nValley of Bonesへ戻り、彼らを解放しなければならない。Gelkisは結束しているのだ。", nil, nil, 0x76503b38, 0x148d8d61, 0x52532c02, nil, nil, "...mm" },
  [93062] = { "骨の埋葬", "Gelkis Clanとの評判を維持し、Valley of Bonesの各地で失敗した召喚体$N1体の呪いを解く。", "あなたのこの杖についてですが、これはUthekのものの一つだと分かります。そしてあなたは、これがTheradras' Tearsで作られ、Draenethyst Crystalで強化されていて、闇の魔法を解くことができると言っていましたね？\n\n谷のさらに奥で、岩だらけの土のすぐ下にスケルトンが埋まって動けなくなっているのに気づきました。Outcast Necromancersの召喚に失敗したものだと思います。おそらく永遠に、土に埋もれたまま存在し続ける運命なのでしょう。\n\n彼らを再び眠らせることは、我々の大義にとっても、彼らの魂にとっても良いことでしょう。", nil, nil, 0x25960f2c, 0x00d4e816, 0x21e3a666, nil, nil, "...mm" },
  [93065] = { "戦いへの備え", "Gustberry LowlandsのValennia Stormfistと話してください。", "Peacekeepersが動員され、我々は皆出発の準備を整えている。必要な準備を済ませたら、町から北へ出る東の道で我々と合流してくれ。出発前に、全員と最後の確認を1回行う。", nil, "これ以上ないほど準備は整った。", 0x5db1f556, 0xd94373fd, 0x8619e90a, nil, 0xda1d39ff, "...m." },
  [93066] = { "Bristleback Retreat", "Magramとの評判を維持し、Bristleback Retreatでquilboarを倒す。それからDesolaceのValley of Bonesの反対側にあるMagram FrontのHagiakのもとへ報告に行く。", "谷の向こう側に、近くの森へ進軍する準備のための小さな足場を築いた。そこへまっすぐ向かう前に、途中で起きた最近のBristlebackの侵入に対処してほしい。奴らは我々とほぼ同じ頃にやって来たようだが、近くの神殿から遺物を手に入れ、それで我々を寄せつけずにいる。\n\n仕事は簡単だ。トゲと豚を探せ。片っ端から大勢倒せ。それから私が言った野営地のHagiakに報告しろ。", nil, nil, 0x6802c038, 0x895f28cd, 0x20e4bcb9, nil, nil, "...mm" },
  [93072] = { "長期的な解決策", "Magram氏族との評判を維持し、Outcast Scoutsを$N1体、Outcast Maraudersを$N2体、Outcast Necromancersを$N3体倒してから、Magram FrontのHagiakのもとへ戻る。", "この辺りには、南西にもう一つcentaurの村がある。そちらはGelkisのものだ。ただ血を流させるためだけに俺がお前を送り込むと思っているんだろう？いいだろう。最初にそう考えるべきだ。さもなければ、お前のMagramへの忠誠を疑うところだ！\n\n何を待っている？行け！殺せ！", nil, nil, 0xaf937461, 0x1208c910, 0xd1a41853, nil, nil, "...mm" },
  [93089] = { "この先に待つもの", "Zephras Isleを発つ準備ができたら、Elaadrin Evengaleと話してください。", "High Orderと、この「Kirin Tor」から来たあなたの新しい友人たちがZephras Isleのためにしてくれたすべてのことに対し、Elaadrinに私からの感謝を伝えてください。High Orderが島を去る計画は承知しています。この遠征にあたり、あなたがたの教団には私の祝福と幸運の祈りを送ります。\n\nHigh Orderが見つける秘術の解決策が何であれ、ここ数年私たちに欠けていた安定を本当にもたらしてくれることを願うばかりです。もしあなたも彼らと共に行くつもりなら……そうですね、この任務はそれだけ心強いものになるでしょう。\n\n風があなたと共にありますように、{name}。", nil, "我々の遠征にHigh Elder Shadowsongの祝福があると聞いてうれしく思います。教団は打ち倒され、準備も整いました。ついにその時が来たと思います。\n\nAnsiremは、Dalaranの都とZephras Isleの間で安定したskycutterの輸送を実現するために、熱心に働いてくれました。できる限りの試験は済ませました。我々の先遣隊が出発する時が来たのです。", 0x50a257df, 0xb2d66ffb, 0xa384a68c, nil, 0xd86a7736, "...m." },
  [93090] = { "この先に待つもの", "Zephras Isleを発つ準備ができたら、Ayessa Dawnsingerと話してください。", "Windshapersと、この「Earthen Ring」から来たあなたの新しい友が、Zephras Isleのためにしてくれたすべてのことに、私からの感謝をAyessaに伝えてください。Windshapersのシャーマンたちを連れて島を離れる計画は承知しています。あなた方の教団には、この遠征への私の祝福と幸運の祈りを送ります。\n\nWindshapersがどんな解決策を見つけるにせよ、ここ何年も私たちに欠けていた安定を本当にもたらしてくれることを願うばかりです。\n\n風があなたと共にありますように、{name}。", nil, "我々の遠征にHigh Elder Shadowsongの祝福があると聞いてうれしく思う。教団は打ち倒され、準備も整った。ついにその時が来たと思う。\n\nMulnは、Zephras Isleと、Earthen Ringが拠点とするMulgoreという地の間で安定したskycutterの輸送を実現するために、熱心に働いてくれた。我々は試験航行を続けていて、仲間の一部はすでに向こう側で待っている。", 0x50a257df, 0x42ef0bb4, 0xfa29d4a6, nil, 0xeaba7e66, "...m." },
  [93122] = { "様子を見に行く", "Gelkisとの評判を維持し、Shen'dralas内にあるcentaurの重要な場所を調べる。それから、見つけたものを持ってValley of Bonesの入口にいるNerlokhのもとへ戻る。", "我々は皆、この地域におけるMagram氏族の力と存在感を見くびっていた。だが、これは好機になるかもしれない。\n\nこれほど多くの者が気を取られ、しかも他の氏族からの追放者を受け入れようとしない。ならば、村を守るのは誰だ？奴らのKhanはどうなる？\n\n谷の中へ、これまでよりも深く入って、辺りを調べてきてくれ。もしMagramがここで見た目どおり守りを固めているなら、自分たちの村を無防備にしているかもしれない……", nil, nil, 0x9009cbea, 0x26ae294d, 0x1c056f62, nil, nil, "...mm" },
  [93125] = { "帰郷", "Gelkisとの評判を維持し、RokrenをOutcast Hideawayから護衛して連れ出す。それからValley of Bones近くのNerlokhに何が起きたかを伝える。", "あなた！外で追放者たちと戦っているのを見ました。どこから来たのかは知りませんが、あなたの助けが必要です。\n\n私は安全を保証するというGelkisの同胞たちの言葉に誘われて、ここへ来ました。Desolaceの戦争が私たちの手に負えないほど激しくなっていることは知っていましたが、まさか自分の同胞が死霊術に手を染め、Magram氏族へ寝返ろうと入り組んだ企てをするとは思ってもいませんでした。私がこれに反対すると、このテントから一歩でも蹄を踏み出したら殺すと脅されたのです！\n\nどうか助けてください。", nil, nil, 0xf193b151, 0x86ad2352, 0x15267230, nil, nil, "...mm" },
  [93127] = { "山頂の歩哨", "Blackthorneの信者たちの周りの北、西、南にある見張りの石を再起動してください。", "Wild Kingは数では勝っているかもしれないが、我らは戦術で出し抜ける。\n\n周りを囲む丘にある、我らの生きた歩哨石に力を与えてくれ。あれならBlackthorneの動きを追ってくれる。北の尾根、南の斜面、西の高台には、力の尽きた石がある。味方であるお前の存在を感じ取れば、目を覚ますはずだ。\n\n作業中は慎重に動け。この道にはBlackthorneの巡回兵がひしめいている。奴らがいるからこそ、この地を油断なく見張らねばならないのだ。", nil, nil, 0xe616b857, 0x21d2e6f5, 0x0ded7b03, nil, nil, "...mm" },
  [93128] = { "Khan Jehn", "Gelkisとの評判を維持し、Magram VillageでKhan Jhenを倒す。成功したら、DesolaceのGelkis VillageにいるUthek the Wiseのもとへ報告に行く。", "UthekかKhan Shakaに命令を下してほしいところだが、好機の窓は短いのではないかと恐れている。Gelkis Villageの者たちに相談するには短すぎる。\n\nここValley of Bonesで事態が動いている今、MagramはKhan Jehnの守りを最小限にしたままだと思う。他の氏族のKhanを攻めるときがあるとすれば、今だ。\n\nだが{name}、Khanは侮ってよい相手ではない。Jehnならなおさらだ。動く勇気があるなら素早く動け。だが奴を見くびるな。", nil, nil, 0x67d27eda, 0xe9180567, 0xe9fc8e6f, nil, nil, "...mm" },
  [93129] = { "飢餓の脅威", "Magramとの評判を維持し、Stolen Suppliesを$N1個、Magram FrontのHagiakのもとへ持ち帰る。", "お前はやけに我々の氏族を助けたがっているようだから、Outcast Hideawayに行っている間に物資を取ってきてくれるだろうな。\n\n敵を倒すことはMagramにとって十分な動機になるはずだが、そのついでに我々が得をしてはいけない理由もない。\n\n追放者どもを片付けたら、この場所をMagramのために確保し、軍を集めて他の氏族をひざまずかせてやる！", nil, nil, 0x73784842, 0xa76555fc, 0xd084fd3d, nil, nil, "...mm" },
  [93159] = { "奇妙な隠者", "Shadowgale ForestのStrange Hermitと話し、彼についてもっと知ってください。", "あ、えっと……こ、こんにちは、いや、その、やあ！ご、ご挨拶を、というか！ごめんなさい……その、ほかの人と実際に話すのは、すごく久しぶりで。ちょっと慣れていないみたいです。\n\n<奇妙なフードの人物は、あなたの前で居心地悪そうに身じろぎする。>\n\nそれで、えっと、その……今日はどんな一日ですか？", nil, "……それについて言えるのは、だいたいそれくらいかな。ここに来る前は、えっと、どこか別の場所にいたんだ。今はここにいて、友達もいるし、自分の物もある。つ、つまり、自分で作った物のことだけど。必要なのはそれくらいかな。とにかく、必要なのはそれだけだと思う。\n\nでも、言っておきたいんだけど、話し返してくれる相手と話せるのはうれしいよ。森の精霊たちも頑張ってはくれるけど、結局は僕に向かって歌い出しちゃうんだ。それはそれでいいんだけど、し、刺激的な会話とは言えないよね。", 0xc281d56b, 0x91510117, 0x813fe37d, nil, 0xf694abb5, "...m." },
  [93160] = { "森の恵み", "Shadowgale ForestでShadowgale Acornを$N1個集めてください。", "話しに寄ってくれて本当に嬉しいです！ も、もし手伝ってくれるなら、森の地面からどんぐりを集めるのを少し手伝ってほしいんです。近くのはほとんど集めたんですけど、森にはraptorみたいな鳥がすごくたくさんいて。外は危ないし、巨大な鳥のお昼ごはんにはなりたくないんです！\n\nだから、もしよかったら、集めてきてもらえませんか？ そうしてくれたら、何かおいしいものを作りますね！", "うーん、このドングリでこしらえる料理、きっと気に入ってもらえると思うよ！", "ありがとう、旅の人！焼いたらこれがとってもおいしいって分かるよ！\n\nちょっと失礼するね。これを手早く作るのに、そう時間はかからないから。", 0x4aa75777, 0x076dacd0, 0xb98c76cc, 0xd9fab18b, 0xc1c8b911, "....." },
  [93161] = { "Ancient Hilt", "Ban'aethalの遺跡で見つけたAncient Hiltに興味を持ちそうな人物を探す。", "松明のかすかな明かりの中に、小さな金属のきらめきが見える。よく調べてみると、それが古代の剣の折れた柄であることは明らかだ。\n\n刃は失われているものの、この柄が見事な職人技の産物であることははっきりと分かる。これは貴重な家宝であり、これについてもっと知りたがる者がいるかもしれない。", nil, nil, 0x6be8180e, 0x4a6d29a7, 0x44c924e0, nil, nil, "...mm" },
  [93162] = { "Head of the Obliterator", nil, "君は確かに私に力を示してくれた、{name}。だが、我が部族の他の者たちはそう簡単には納得しない。そのためには、Legashiとの戦いを続けてもらう必要がある。\n\n倒したLegashiのsatyrの角を持ってきてくれ。君が持ってくる束の一つ一つが、Blackmawへの君の奉仕の証となるだろう。", nil, nil, 0x5d215c20, nil, 0xb1c3b2ab, nil, nil, ".m.mm" },
  [93163] = { "Heart of the Obliterator", "Heart of the ObliteratorをThorium Pointへ持って行ってください。", "作られ、そして再び壊された。Iodax the Obliteratorのheartは今、あなたの手の中にある。このゴーレムはおそらくdark ironのドワーフか、それ以前の何者かが発明したものだろう。だとすれば、Thorium Pointのドワーフたちが、ここでのあなたの発見に興味を持つかもしれない。", nil, nil, 0xd743fc17, 0xb2f54aa1, 0xd8bbee31, nil, nil, "...mm" },
  [93165] = { "慈悲は聞く耳を持たぬ者に", "Shadowgale Forest、Shrine of Akir、またはGustberry LowlandsにいるAl'Akethの教団員からAl'Aketh Cultist's Earを$N1個集めてください。", "Al'Akethは我らの集落に大いなる悲劇をもたらした。血は血で償わせねばならぬ。\n\nよそ者よ、そなたに申し出がある。この呪われた教団員どもと争うことがあれば、倒した者の耳を持ってくるがよい。持ち帰った耳ごとに金で報いよう。そして、そなたが真の友であると証明すれば、いずれNightclawの秘密に触れることも許そう。", "この島の教団員を一人残らず、その喉笛をこの牙で食い破るまで、私は休まない。", "見事な働きだ。教団を排除して起こるのは良いことだけだ。これで、Nightclawは侮れない相手であり、我々の恨みは深いのだと思い知らせることができればいいが。\n\n教団を相手にするとなれば、お前もさぞ骨が折れることだろう。もっと耳を集めたら、ここへ持ってこい。", 0x67167132, 0x29ccfeb1, 0xf3604d96, 0x3dfb4bed, 0x1c83ddb0, "....." },
  [93172] = { "Hollowsの解放", "Shadowgale ForestのWind Hollowsを10個破壊してください。", "この島のエルフのほとんどは、この森には幽霊が出ると思っていて、それは間違いじゃない。\n\n北東の古い遺跡には、幽霊のような奇妙な霊たちが集まっている。夜によっては、彼らが「歌っている」のがほとんど聞こえるほどだ。今までに聞いたどんな歌とも違うけど、確かに歌で、それが……とにかく悲しいんだ。\n\nなぜかは分からないけど、いつかあそこで何か恐ろしいことが起きて、霊たちがどういうわけかそこに閉じ込められているんだと思う。勇気があるなら、彼らを解放する手助けをしてくれないかな？", "あの哀れな魂たちが、この場所から解放されて安らぎを見つけられるよう、願うしかない。", "ありがとう、旅の人。", 0x0e18dc30, 0x1267d2ac, 0xe5c300d2, 0xb1bfb39d, 0x66dd9c71, "....." },
  [93173] = { "（未使用）Rusty Gadget", "Rusty GadgetをShadowgale ForestのThe Strange Hermitのところへ返す。", "<Wind Hollowをひとつにまとめていた渦巻く気流が消え始めると、小さな金属の装置があなたの足元の地面に転がり落ちた。何かの機械仕掛けの道具のようだ。The Strange Hermitは、まだいくつかの装備が見つからないと言っていた。彼ならこれに興味を持つかもしれない。>", nil, nil, 0xd8c783cf, 0x3216fc08, 0x02764b22, nil, nil, "...mm" },
  [93176] = { "私の小さな友達", "Entomology Starter Kitに入っている道具を使って、Arbor Tarantula、Hay Weevil Specimen、Flesh Pickerを見つけて捕まえる。", "私のささやかな動物園に見とれているのかね？これは私の不死の生涯をかけた研究だ。数え切れないほどの時間をかけて調べてきた。その体の構造、食性、さらには社会的な儀式までもね。\n\n君もこの趣味に加わりたいかね？さあ、この包みを持っていきたまえ。中に入っている記録と道具があれば始められるはずだ。なくしたら、少額の料金で私からもう一つ買ってもらうことになるよ。", nil, nil, 0xd9137740, 0x98c50d57, 0xc04ef699, nil, nil, "...mm" },
  [93188] = { "Orgrulのもとへ戻る", "Magramとの評判を維持し、Valley of Bonesの北の入口近くにいるOrgrulのもとへ報告に戻る。", "お前は前線で十分に働いた。我々だけでやっていける。\n\nOrgrulに、お前の役目は果たしたと伝えろ。Magram Frontは今や強くなった。また別の戦士の一団が戦いに加わったら、我々の次の拠点として追放者の野営地に狙いを定めている。\n\nどうした？さっさと行け！", nil, nil, 0x14b1f8e5, 0x30764b3d, 0x99bb3d87, nil, nil, "...mm" },
  [93196] = { "Khan Jehn", "Magramとの評判を維持し、死霊術の儀式を行ってKhan Jehnを蘇らせる。儀式の場所はMagram Villageの中央の湖にあるテントの中にある。", "我々の氏族の長、Khan Jehnは、お前のようなよそ者の一団に殺された。奴らはGelkis Clanのために動いていた。\n\n驚いたふりはやめろ。我々の目がよそに向いている間にMagram Villageを襲うのは、予測できる戦略だ。特にGelkisにとってはな。\n\nよそ者よ、なぜ俺が怒りも後悔も見せないか分かるか？\n\n<Orgrulは見覚えのある武器をあなたに手渡した。前にあなたが手にした時よりも、さらに強い力が込められている。>\n\nこれがその理由だ。", nil, nil, 0x67d27eda, 0x571f4b9c, 0xc11d031e, nil, nil, "...mm" },
  [93197] = { "通信の修復", "Mount Hyjalの山頂のキャンプにいるSebeliaから郵便の小包を受け取り、EverlookのInnkeeper Vizzieのところへ届けてください。", "戦いが続き、Nordrassil Lodgeから撤退したせいで、ここはひどい人手不足なんです。\n\nこことEverlookを行き来するのなら、配達のために町へ送らなければならない郵便物があります。それに、向こうで待っている郵便物もこちらへ持ち帰ってほしいのです。運ぶ準備のできた小包が山ほどあります。手伝っていただけるとありがたいのですが。", nil, nil, 0x03ce7777, 0xc50a4259, 0x444f3370, nil, nil, "...mm" },
  [93224] = { "Carved Centaur Totems", "Desolace各地でどの氏族のcentaurでもよいので倒し、Carved Centaur Totemsを$N1個手に入れる。それからNijel's PointのCaptain Pentigastに届ける。", "どちらのcentaur氏族も、自分の氏族以外の者からの助けを受け入れたがらないってのは、たぶん驚くことじゃないだろう。特に、あんたや俺みたいな連中、つまりcentaurじゃない者にはね。\n\n俺たちみんなに共通しているのは、金は力だってことを分かってるってことさ。で、地元のcentaurは彫った木で物々交換するって分かったんだ。奴らの彫り物の見本をいくつか持ってきてくれれば、似たような彫刻を急ぎで注文できる。そうすれば有利な立場を買えるかもしれないぜ。", "トーテムを持って戻ったか？", "私はcentaurではないが、これは十分なトーテムの束に見える。彼らの蹄鉄を履いた身になって考えれば、これを贈られたら大喜びするだろう。君が出かけている間に、私もいくつか手に入れておいた。\n\n届ける準備ができたら話しかけてくれ。我々がどの氏族につくか、君なら正しい選択をしてくれると信じている。", 0x9d52128a, 0xa608090a, 0x7f0dbe84, 0xdffc89ab, 0xed457215, "....." },
  [93225] = { "Carved Centaur Totems", "Desolace各地でどの氏族のcentaurでもよいので倒し、Carved Centaur Totemsを$N1個手に入れる。それからGhost Walker PostのGurda Wildmaneに届ける。", "違う氏族のcentaurが、時々集落から離れた場所に集まって交易をしているのに気づいた。幾晩にもわたって、しかもどうやらすべての氏族でそれを見てきた。何より重要なのは、奴らが使う通貨を見たことだ。彫ったトーテムだ。\n\n重いトーテムの束を直接届ければ、GelkisかMagramのどちらかとの形勢を有利に変えられると思う。もういくつか彫り始めているが、本物がいくつかなければ、奴らも簡単にはだまされないだろう。", nil, nil, 0x9d52128a, 0x19fc2936, 0xb3fe9d43, nil, nil, "...mm" },
  [93226] = { "友好を買う：Magram", "Totem ToteをDesolaceのMagram VillageにいるMagram Quartermasterに届け、その氏族との評判を大きく上げる。Magram Clan Centaurとの関係が中立以上でなければならない。", "私ならMagramにつく。過去にどんな苦難があったにせよ、今の時代、奴らが支配的な氏族なのは疑いようがない。奴らがGelkisに対して残忍なほど敵対的だという報告も聞いている。\n\n争っている両方の氏族に、特にGelkisには同情するが、これは奴らの戦争であって、我々の戦争ではない。我々の大義にとって最も危険の少ない勢力につくべきだ。私はそれがMagramだと思う。\n\nこれを南東のMagram Villageにいる奴らの補給係に届けてくれ。", "よそ者がGorhakに何の用だ？", "<彫刻されたトーテムの束を差し出すと、Gorhakは目を見開いた。だが、その目が再びあなたの方へ向けられると、彼は眉をひそめた。>\n\n我は愚か者ではないぞ、よそ者。この寄付には理由があるはずだ。お前は何かを望んでいる。我からか、我らの氏族からか。それが何かは知らぬ。\n\n<補給係は手のひと振りで、袋を自分のものにした。>\n\nだが今日のところは、お前の下心が何であろうとかまわぬ。\n\nMagram Villageへようこそ、よそ者。", 0xf5fd14ba, 0x66df78e4, 0xe1f3c90b, 0xb619ffad, 0xcdce9709, "....." },
  [93227] = { "友好を買う：Gelkis", "Totem ToteをDesolaceのGelkis VillageにいるGelkis Quartermasterに届け、その氏族との評判を大きく上げる。Gelkis Clan Centaurとの関係が中立以上でなければならない。", "一見したところ、Gelkisは苦戦しているように思える。その数はMagramよりはるかに少ないし、偵察兵から奴らが暴れ回っているという話もめったに聞かない。\n\nそれでも、奴らはDesolaceで有力な氏族の一つであり、今日まで生き延びている。何か正しいことをしているに違いない。\n\nGelkisと和平を結びたいなら、このトーテムの袋を持って、はるか南西のGelkis Villageへ行け。原始的な連中ではあるが、何らかの会計係はいるだろう。", nil, nil, 0x57c3db29, 0x68c32afb, 0xc65c6911, nil, nil, "...mm" },
  [93269] = { "拠点の頂上", "Everlookから、Mount Hyjalの山頂にいるInnkeeper Sebeliaのところへ郵便を届けてください。", "郵便物を全部取り戻したんだから、それを全部Mount Hyjalへ持って帰れるな！\n\n何の問題もないだろ？", nil, nil, 0x867c3a9d, 0xd94323a6, 0x3e2903a5, nil, nil, "...mm" },
  [93317] = { "カニの季節", "Windsong Crawler Meatを6つ集めてください。", "Windsong Crawlersをご存じですか？ このカニはここZephrasのWindsong Lakeにしかいなくて、一年のうち数週間しか獲れないんです。\n\n最近の教団の活動のせいで湖まで獲りに行けなくて、時期がどんどん終わりに近づいています。行って少し集めてきてくれたらありがたいです。たいてい湖の周りの岸辺や川沿いにいます。\n\nでも気をつけてくださいね、見た目より凶暴ですから！", "Windsong Crawlerの肉はここではありふれているが、AnvilasやSiroccasの島々ではちょっとしたごちそうだったんだ。空の流れがまだ開いていた頃は、Shen'dramarやNew Eldre'naarへ足を運ぶたびに、地元の連中がこれを求めて押し寄せてきたもんさ。\n\nああいう場所には、もう……そうだな……ずいぶん長いこと行けていない。", "風よ、なんて素晴らしい肉だろう！\n\n本当にありがとう、{class}。", 0x6f40d8c7, 0x3826218b, 0xb3597e4b, 0x9e47a279, 0xca0b8646, "....." },
  [93318] = { "お尋ね者：Vulgara the Insatiable", "Shen'dar HighlandsでVulgara the Insatiableを倒し、その首をDanarii Bellowveilに届けてください。", "PeacekeepersのConstable Aondaの命により、ここに高地の災厄、Vulgara the Insatiableに懸賞金をかける。最後に目撃されたのはShen'dar Villageのすぐ南西の丘の上。翼を持つこのvuldrenの怪物は非常に危険であり、慎重に近づくこと。\n\n報酬を受け取るには、その獣の首をDanarii Bellowveilに届けること。", "やり遂げた証として、その生き物の首が必要だ。", "教団と高地の山賊だけでも手一杯だというのに、巨大なvuldrenにまで市民を脅かされてはたまらない。今日、あなたは素晴らしいことをしてくれた。約束どおり、これが報酬だ。", 0x26deadde, 0x95335eb7, 0x44a54b33, 0x7e44c040, 0xedf3a0ac, "....." },
  [93319] = { "Pilfered Windstones", "Shen'dar HighlandsのHighlands Banditsから、Pilfered Windstonesを10個集めてください。", "ここZephrasでは、日々の暮らしにますますwindstoneを頼るようになっていて、非常時に備えて予備を蓄えておくようにしている。ところが最近、蓄えの中からいくつかなくなっていることに気づいた。\n\n最近捕まえた山賊たちがwindstoneを持っていたから、蓄えが減っているのは奴らのせいだとにらんでいる。\n\n北の山賊の洞窟の近くに行くことがあったら、何人か痛い目に遭わせて、盗まれたwindstoneをいくつか取り返してきてくれないか？", "このこそ泥どもは、何か月も前から私たちの物資に忍び込んでいたんだろう。あの盗賊の洞窟をきっぱり一掃する襲撃隊を組むようAondaを説得しようとしたが、彼女は村からわずかな治安維持の者たちを引き離したがらなかった。\n\n南のFalaath Villageで教団員の数が増えている今、それを責めるわけにもいかないだろうな。", "ありがとう、{class}。これで当面はしのげるはずだ。だが、補給路をすぐに立て直せなければ、盗まれた風の石が少しばかりなんてことは、心配事のうちにも入らなくなるだろう。", 0x41d7b2ca, 0x098aea7b, 0x414845c0, 0x9132cdaf, 0x4e8fd502, "....." },
  [93320] = { "塔の防衛", "Gustberry Lowlandsの東の見張り塔にいるYorana Windyreedに報告してください。", "町のすぐ外にあるパイロンの見張り塔を教団が攻撃しているという知らせが入った！ ここにいる数少ない予備の治安維持隊を送り、敵の後方線を突破して守備隊を救援させようとしているが、少しでも助けが増えれば、あそこにいる仲間たちの生死を分けるかもしれない。\n\nすぐに東の見張り塔へ向かい、できる限りの援護をしてくれ。\n\n救援部隊は私の副官Yorana Windyreedが率いている。彼女がまだ生きていれば、どう助けるのが最善か教えてくれるだろう。", nil, "今のところは持ちこたえているが、敵の数の方が多く、こちらの戦士たちは疲れ始めている。膠着状態を打ち破るために何か手を打たねばならない。それも急いでだ。", 0x0a49deab, 0x7f44b2b4, 0x98ee9961, nil, 0xbdc9cc11, "...m." },
  [93341] = { "Forlorn Gardens", "Shen'dralas近くのForlorn Gardensを調査し、その後近くの神殿にいるMitheraのところへ戻る。", "庭園の世話役として、庭園を栄えさせるのが私の務めでした。\n\nいつか私が手入れをできなくなる日が来ることは分かっていました。だから、娘から贈られた首飾りに魔法をかけ、新しい世代の苗木をトレントに変えて、私の代わりに庭園を見守ってもらえるようにしたのです。首飾りは魔法をかけた台座に置き、小さな祠の中に納めました。\n\n庭園は良い手に委ねられていました。何が起きたのか、知らなければなりません。", nil, nil, 0xd0ba0cf6, 0x0192d9da, 0x65717ea1, nil, nil, "...mm" },
  [93362] = { "私の牡丹になんてことを", "Forlorn Gardenの植物を間引き、その後Shen'dralasにいるMitheraのところへ戻る。", "そこで命がどのように歪められたのか、詳しく話すのはやめてください。首飾りを失っただけで、私の心はもう十分に傷ついています。\n\nけれど、私が泣いている間にも、植物たちは苦しんでいます。\n\n{name}、庭園に戻って、怒れる草木をいくらか間引いてほしいのです。どうか素早く、慈悲深くお願いします。あの子たちは痛みを感じますし、もう十分に傷ついてきたのですから。首飾りを探しに行くつもりなら、庭園をまた訪れる前に、そちらを優先してください……万が一、見つかることがあればですが。", nil, nil, 0x02a410c1, 0x39f93120, 0x9c26e5ed, nil, nil, "...mm" },
  [93383] = { "中身は加圧状態", "Personal Survival Packを安全に開けられるようになるまで待ってください。", "サバイバル用品と無線受信機を詰め込んだ頑丈なバックパックが、とげだらけの茂みの間に転がっている。無線機の一つで表示ランプが点滅している。\n\nバッグに手を伸ばすと、バックパックに縛りつけられた無線機がブーンと音を立てて動き出す。\n\n「パイロットを確認！Gnomal Positioning System、アップリンク確立中！\n\n支給内容を確認：Aviator's Survival Kit、3日分、フリーサイズ、数量1\n\n開封前にセキュリティ装置が安全に放電するまで、しばらくお待ちください。」", nil, nil, 0xd81988f0, 0x793da55f, 0xec9cb1ef, nil, nil, "...mm" },
  [93394] = { "魔導師との面会", "Shen'dralasの神殿の中にいるMagister Kirandisを見つけてください。", "今、あなたの好奇心はあの壮大な建物へとあなたを誘っているのでしょう？いいことです！\n\nそこにいるShen'dralarが両手を広げてあなたを歓迎することはまずないでしょうが、敬意を持って振る舞う限り、面倒なことにはならないと思います。\n\n運が良ければ、私の古い友Kirandisはすぐに見つかるでしょう。皆の中で、彼が一番あなたを快く迎えてくれそうです。", nil, nil, 0x21131543, 0xbaafa318, 0x16504407, nil, nil, "...mm" },
  [93404] = { "腐敗と後悔", "Maraudonへ赴いてVial of Earth Song Waterを回収し、DesolaceのForlorn GardensにいるWoodwyrdのところへ持ち帰る。", "我は古き者。我らの上にそびえ立つもの。幾度の雨にもなお燃え続けるもの。死してなお、その炎を感じる。最後の過ちを永遠に背負って。\n\nなぜこの地に取り憑くよう呪われたのか、我には分からぬ。なぜ死が終わりではなかったのか、理解できぬ。\n\nどうか炎を消してくれ。聖なる峡谷の清らかな水を求めよ。そのような地がMashan'sheの向こうにある。風の中に、その地のささやきを聞いた。\n\nMaraudon。", nil, nil, 0x31232d72, 0x624e3edb, 0x6f389220, nil, nil, "...mm" },
  [93406] = { "解凍された配達物", "Everlookの北の丘で、Missing Mailを$N1個見つけ、Innkeeper Vizzieのところへ持って帰ってください。", "で、返送の郵便物をMount Hyjalへ持って帰らなきゃならないんだって？ちょっとした問題があってな……\n\nいいか、ほんの数日前に誰かがここに来て、出す予定の郵便物を荒らしていったんだ！たぶん郵便物の中の金を探してたんだろう。ここから北の丘のどこかへ逃げて、それっきり戻ってこなかった。どうせイエティか何かに八つ裂きにされたんだろうさ！\n\nとにかく、郵便物を持って帰りたいなら、まずそれを取り戻してこなきゃな！", nil, nil, 0x1b967bbd, 0x31a7b80c, 0xa6dd883b, nil, nil, "...mm" },
  [93407] = { "前足のトゲ", "Mount Hyjalの山頂の森でイバラの種を見つけ、Tiala Whitemaneのところへ持って帰ってください。", "ここの守りを強めなければなりませんが、砦を築く資材がありません。ですが、自然の恵みならいくらでもあります。\n\n森でイバラの茂みを探し、その種を持ち帰ってください。自然の力で、自分たちの守りを育てるのです。", nil, nil, 0x0cdff482, 0x2a63ab68, 0xd1bb5e93, nil, nil, "...mm" },
  [93422] = { "Blackthorneの消灯", "Blackthorne Courierを倒し、彼女の伝言を押収してください。", "Wild Kingは、Hyjalそのものより古い影を通して耳を澄ませている。この聖なる地でHordeとAllianceが再び進軍してきたことに刺激され、奴の斥候たちは今、明確な目的をもって動いている。Blackthorne Pactは我らの抵抗に圧力を感じ、日に日に狂気を増している。\n\nBlackthorne Courierを追い詰め、奴らの重要な情報を主のもとへ持ち帰る前に、その足取りを断て。\n\n彼女は野営地の間を行き来している。その道筋を見張り、討ち取れ。彼女が持っているものを我らのもとへ持ち帰るのだ。", nil, nil, 0x214855c4, 0x2ac6a8b8, 0x619edddf, nil, nil, "...mm" },
  [93429] = { "血を分けた者", "Fallow SanctuaryでLost Onesを10体倒す。", "彼らは我々の同族ですが、Fallow SanctuaryのLost Onesは純粋な暴力と憎しみの存在になってしまいました。\n\n彼らに贖罪や救いはありえません。彼らは生涯、心を失った憎しみに満ちた生き物として、この沼地をさまよう運命なのです。\n\n彼らの苦しみは終わらせなければなりません。誰かが彼らを苦しみから解放してやらねばならないのです。むごい仕事なのは分かっています。それでも、残された我々を守るために、やってくれませんか？", nil, nil, 0x18916a9d, 0x3b5f5f4a, 0xdbc3d8f8, nil, nil, "...mm" },
  [93430] = { "餌を取り返す", "Pellukのルアーを盗んだLost One Fishermanを見つけ、それを取り返す。", "今度こそ本当にやってくれたな！あの哀れな連中だけでも手を焼いているというのに、そのうちの一人が俺の幸運のルアーを盗みやがった！\n\n今朝釣りをしていたら、奴らの一人が泥の中から出てきて、俺の釣り糸を切って、ルアーを持ち去ったんだ。泥棒はまず間違いなくLost Onesの釣り人の一人で、自分でそのルアーを使うつもりなんだろう。\n\nとにかく、俺たちの魚の供給はあのルアーにかかっているんだ。だから取り戻したい。Lost Onesはここの東の岸辺で釣りをしている。その泥棒を見つけてくれ、{race}！", nil, nil, 0x42cf1db9, 0xb7ae8a79, 0x115f80e5, nil, nil, "...mm" },
  [93443] = { "Lost Shipping Crate", "Lost Shipping CrateをRivergladesのPowderfuse PortにいるFriz Frazzlesparkに届ける。", "<木箱の側面に手書きのラベルが貼られている。右側には地図があり、水に囲まれた下手くそな神殿の絵と、何やら翼のある生き物が描かれ、その北の南東の海岸線に大きな赤い丸がついている。左側には、とても大きな文字でメモが書かれている。>\n\nFRIZ FRAZZLESPARKの所有物\n\nPOWDERFUSE PORT\n\n警告：いじるべからず。監督なしで絶対に開けるべからず。\n\n<ラベルの下に、さらにメモが書き足されている。>\n\n紛失した場合はFriz Frazzlesparkまで返却のこと。Powderfuse Port。Riverglades。", nil, nil, 0xc2fa676d, 0x4f011a57, 0x87144b02, nil, nil, "...mm" },
  [93444] = { "獣をおびき寄せる", "Nightsaber Guardianを倒し、山頂の北の尾根でNightsaber Guardianの腿肉を使ってGhansurokをおびき出して倒してください。\n\nキマイラの心臓を持って帰ってください。", "Hyjalで最も凶暴なフェルのchimaeraは、Ghansurokとして知られてる。巣穴から出てきた野生動物に急降下して襲いかかるのが好きなんだ。それだけじゃない。そのせいで、Hyjalを出入りするhippogryphの旅がいつも以上に気の張るものになってる！\n\nまず、Summitの影に隠れているNightsabersを一頭狩ってくれ。次に、倒した猫の肉を、chimaerasが餌をあさる北の尾根のどこかに置くんだ。\n\nGhansurokをそこへおびき寄せろ。そいつを倒して、心臓を持って帰ってきてくれ。Marnがそれを調べて、Hyjalを癒やす助けにする。", nil, nil, 0x3ef62b1d, 0x058f9d3e, 0x3a9a99d1, nil, nil, "...mm" },
  [93450] = { "幻影の問題", "Vindaelの未完成の剣を受け取り、それを霊界へ送る方法を見つけ、Shen'dralasにいる彼のところへPhantasmal Bladeを持って帰ってください。", "知ってのとおり、肉体があるのもそれなりに大変だが、肉体がないとなるとまったく別の話だ。この椅子をすり抜けて落ちやしないか？あの猫につまずきやしないか？だが何より最悪なのは、日々の仕事ができなくなることだ！\n\nわしの金床の上のこの剣が見えるか？何千年も前に作り始めたんだが、仕上がる前に死んでしまった。今ではこいつがわしをあざ笑い、しかも大事な場所を占領しておる！これでは仕事ができん！動かすこともできん！\n\nこいつを霊界へ、その、「渡す」のを手伝ってほしいんだ。どうだ？", nil, nil, 0xd72e86cf, 0xcbd84beb, 0x9039f695, nil, nil, "...mm" },
  [93459] = { "さらなるAl'Akethの耳", "Shadowgale Forest、Shine of Akir、またはGustberry LowlandsにいるAl'Akethから、Al'Aketh Cultist's Earsを10個集め、Shadowgale ForestのVayn Moonclawに届けてください。", "Al'Aketh cultは普段、この森に幽霊が出るという噂を恐れて近づかない……その噂は我々が喜んで保っているものだ。我が結社のドルイドたちは、ここShadowgaleで静かで平和な暮らしを望んでいるだけなのに、奴らはそれを脅かしている。\n\n我々の多くが恐れている。\n\n申し出がある。我々の代わりに教団員と戦い、倒した者の耳を持ってきてくれ。持ち帰った耳ごとに金で報いよう。そして、君が真の友であると証明すれば、いずれ我々の秘密に触れることも許そう。", "<Vaynはあなたにうなずいた。>", "約束どおり、これが報酬だ。", 0x91339b63, 0x4cc2e33c, 0x184326a2, 0xe91596f9, 0x53f5cf99, "....." },
  [93461] = { "Shen'dar Villageへようこそ", "Shen'dar VillageのRathiril SunlanceとCoriella Calmbreezeと話してください。", "君には「High Order」の雰囲気があるね。Highborneの血を引く者は、いつも目に少しきらめきがあるから分かるんだ。ここで本格的に働いてもらう前に、ここに住むHigh Orderの長老、Rathiril Sunlanceに挨拶しておくといい。ここ本館の、私のすぐ角を曲がった所にいるよ。\n\nああ、それとCoriella Calmbreezeにも顔を出しておいて。地元の宿屋をやっていて、必要なら宿と物資を用意してくれる。", nil, "Rathirilには顔を出してきたかい？よし。近頃はHigh OrderとWindshapersの間がかなりぴりぴりしているけど、ここShen'darでは礼儀を保ってるよ。まあ、少なくとも村の中ではね。荒野で起きたことは荒野に置いていくのさ。\n\nそれが済んだなら、あんたは手を動かす仕事を探していそうな顔をしてるね。やってほしいことがいくつかあるんだ。ちょっと働いてみる気はあるかい？", 0x4c9d3c02, 0xe867665b, 0x8517821c, nil, 0xbc58bc08, "...m." },
  [93464] = { "訪れたメイジ", "draenethystの力のことを知っているDesolaceのメイジを見つける。", "一つ打ち明けさせてください、{name}。draenethystは我々にとって神聖なもので、我々の正気を保ってくれていますが、ここにいる誰もそれを完全には理解していないのです。\n\nかつてDesolaceからHarborageへやって来たメイジを覚えています。Azoreという名の人間でした。彼はdraenethystの力を恐れ、悪い者の手に渡ってはならないと言っていました。\n\n当時、我々は自分たちのものを守るために彼を追い払いました。しかし最近、彼が一体何を知っていたのか考えるようになったのです。\n\nこのメイジを探してください、{race}。彼の知識は我々にとって計り知れない価値があるかもしれません。", nil, nil, 0x8dd4d8e6, 0x5dd0e284, 0x339bbfeb, nil, nil, "...mm" },
  [93465] = { "Draenethystについての覚え書き", "GimashiのDraenethystに関するメモを受け取り、Azore Aldamortのもとへ持ち帰る。", "draenethystについて少しばかり知っている者を知っている、と言った方が正確でしょうね。\n\nBurning Bladeのウォーロックたちがそれを研究しているのです。それは闇の門の向こうから来た物質ですから、闇の術に関わる者たちが自らの目的のためにそれを利用したがるのも当然でしょう。もちろん、そんなことを許すわけにはいきません。\n\nあなたが探すべきウォーロックはGimashiという名です。彼女は南東の峡谷にある塔の頂上にいます。彼女の記録に、あなたの求める答えがあるはずです。", nil, nil, 0x187f109c, 0xbf8231d0, 0x92cd47bd, nil, nil, "...mm" },
  [93510] = { "記憶を呼び覚ます", "War Veteranが子供の頃から覚えているLake Everstillの錨を見つけてください。", "多くの仲間が非業の最期を遂げたHyjalに立つのは、重いことだ。大地そのものが悲しみに響いている。灰に満ちたクレーター、忘れるにはあまりに苦い記憶。\n\nだが君は、この陰鬱さに抗うぬくもり、Eastern Kingdomsの火花を宿している！幼なじみの友Tobinは私と共に志願した。希望は持っているが、彼の魂に残されたものを案じている。\n\n子どもの頃、我々はRedridgeのLake Everstillで、午後じゅう水切りをして過ごしたものだ。岸辺の錨を探して、我々の遊びをしのんでくれないか？", nil, nil, 0xb7e57583, 0x8561a9dd, 0x71592518, nil, nil, "...mm" },
  [93521] = { "神々への挑戦者", "Ve'han's Research NotesをTiala Whitemaneのところへ持って行ってください。", "Ve'han's research notesには、主であるWild Kingの野望に従い、Wild Godsの力を盗もうとした彼の試みが記されている。成功はわずかで、不運なものだった。もっと強力なドルイドであれば、Jeremanの精髄をたちまち食らい、さらに大きな力を手に入れていただろう。\n\n頂上の野営地にいるGuardians of Hyjalは、きっとこのことを知りたがるだろう。", nil, nil, 0x951c7368, 0xb149e0e3, 0xb771bdfa, nil, nil, "...mm" },
  [93546] = { "Spectral Iron Ore", "Shen'dralasの周辺でSpectral Iron Depositを探し、Spectral Iron Oreを$N1個集める。十分に見つけたら、Shen'dralasにいるVindaelのところへ戻る。", "ついに、ついにこの金床を、とんでもなく重いテーブル以外のことに使える！何世紀も腕を磨けずにいたが、ようやくまた技を研ぎ澄ませられるとは嬉しい限りだ。\n\nさて、君はおそらくこう思っているだろう。「Vindael、また頼み事の前振りみたいだな」と。その通り！\n\n鉄の蓄えを補充したいのだが、君たちの鉄も私の刃と似た窮地にある。幸い、解決策はずっと簡単だ。\n\n<彼は断る隙も与えず、幽霊のようなつるはしをあなたに手渡す。>", nil, nil, 0x37890077, 0x8f2f06e2, 0xf348b687, nil, nil, "...mm" },
  [93547] = { "厄介な解決策", "忠誠派のドルイドのキャンプにある宿屋、貯蔵塔、木立の近くにイバラの種を植えてください。", "ここは常に脅威にさらされています。Blackthorne Pactからも、Hyjalの敵意ある生き物たちからも。ですが、イバラを味方につけることはできます！自然の力を少し借りれば、新しいイバラの茂みを育てて、私たちの囲いを守る助けにできるのです。\n\n道の近くにイバラの種を植えて、宿屋のそば、貯蔵塔のそば、そして道の近くの木立のそばにバリケードを作る手助けをしてください。", nil, nil, 0xfc8425cb, 0xce47b782, 0xacd69a25, nil, nil, "...mm" },
  [93551] = { "称賛", "Embroidered Scabbardを使い、Mount HyjalのMourning's Restにある壊れた大砲の近くでVeteran of the Third Warと会ってください。", "消えかけた迷える魂の願いのために、わざわざ足を運んでくれた。ありがとう、{name}。湖にもう一つの魂がいて、どちらが遠くまで投げられるか競い合った二人の友を思っている。その光景だけで、私をこの時へ引き寄せるには十分だ。存在とは、生者との最も強い絆にすがりつくものなのだ。\n\n結局、向こう岸まで石を跳ねさせることはできなかったな……\n\n<亡霊は湖の向こうを見つめる。>\n\n思い出した。Mourning's Rest、我々の最後の戦いの地で会おう。崖の上の崩れた塔の近く、壊れた大砲の横だ。", nil, nil, 0x778df3da, 0x935c01b0, 0xb8fb452d, nil, nil, "...mm" },
  [93552] = { "Windstonesの採取", "Thendal GroveのRaw Windstonesから、Windstone Clustersを15個集めてください。", "windstoneはZephras Isleにとって欠かせない資源だ。風そのものの、生の凝縮されたエネルギーを宿しているからな。かつてここZephrasで我々と共に暮らしていた風のエレメンタルたちは何年も前に姿を消し、それ以来、この島を支えている魔法は少しずつ薄れつつある。限界がないわけではないが、windstoneは今でも頼れるエネルギー源で、我々にとって非常に貴重なものだ。\n\nこの木立のあちこちに、未加工のwindstoneが散らばっている。採集するのを手伝ってくれないか？", "やあ、{class}。", "これを本当にありがとうございます。エルフである私たちは皆、魔法と深くつながっています。大いなる錨の柱がこの島に吹き込んだ魔法が薄れ続けるにつれて、この風の石はますます貴重になっているのです。\n\nこの地から採れる役立つ物は、風の石だけではありません。どうぞ、この手引書を一冊お持ちください。", 0x2bcfca6e, 0xe8cd67c8, 0x3a9bfe02, 0x1c31b804, 0x7fc437ff, "....." },
  [93567] = { "やりくり", "Mourning's Restの壊れた大砲のそばで、Veteran of the Third Warに彼の物語を語らせてください。", "南東のこの山の崖……塔の残骸。私の心に焼きついた彼らの悲痛な叫びは、今も記憶の中で永遠に響き続けている。\n\n胸のつかえを下ろして、私の敗北について話させてくれ。", nil, nil, 0x820c93b5, 0xabb89cb9, 0x5423ebd7, nil, nil, "...mm" },
  [93568] = { "Partially Digested Collar", "Partially Digested Collarを、それについて知っている人物に返す。おそらく、DesolaceのShen'dralasかその近くで見つかるだろう。", "<あなたは倒した生き物の腹から取り出した、汚れた首輪を手にしている。上質な革でできていて、丁寧に縫われているのが見て取れる。\n\n腐食した留め金から札がぶら下がっている。汚れを拭い取るとThalassianの文字が見えるが、文字は読めないほど飾り立てられていて、この言語に通じた者でさえ読めないかもしれない。\n\nさて、あなたは選択を迫られている。これを無視して自分の人生を歩み続けるか、それとも不可能に挑み、持ち主に区切りをもたらそうとするか。>", nil, nil, 0xf3699d03, 0x442eb618, 0x9cdce901, nil, nil, "...mm" },
  [93572] = { "Draeneiに仕える", "Kum'ishaの裂け目を通ってOutlandへ向かうdraeneiの難民たちを守ってください。難民は一人も死なせてはいけません。", "お前はKum'ishaにdraenethystの球を持ってきたかもしれん。だがそれはお前が運がいいことを示しただけで、腕があることを示したわけではない。報酬が欲しければ、Kum'ishaの同胞が故郷へ帰るのを手伝うのだ。\n\nKum'ishaはこの球を使って裂け目を開く。その間に、ほかのdraeneiが通り抜ける。何が出てこようと、お前が戦え。Kum'ishaの兄弟姉妹が一人でも傷ついたら、報酬のことは忘れるがいい。\n\n準備はいいか、{race}？", nil, nil, 0x10a57fba, 0x6c75ef2f, 0x15570c74, nil, nil, "...mm" },
  [93574] = { "Corpsefeeder's Carapace", "Corpsefeeder's Carapaceに興味を持つ人物を探す。", "<ひどい音を立てて、あなたはワームが息絶えると同時にその甲殻の一部を剥ぎ取った。\n\nその巨大な大きさとずっしりとした重さにもかかわらず、それは拍子抜けするほどありふれたものだった。この生き物は、残酷な実験の産物でもなければ、すべてを喰らう獣として念入りに育てられたものでもないようだ。\n\nそれはただの見事な殻にすぎず、欲しがるのはおそらく収集家くらいだろう。誰か見つけられるかもしれないが、centaurのほかに、このあたりで生きている者がいるだろうか？>", nil, nil, 0xb71e239b, 0xc953a6e7, 0x2be73f97, nil, nil, "...mm" },
  [93584] = { "教団の幕引き", "Blackthorne Adeptsを$N1体とWild-branded Cultistsを$N2体倒してください。", "Well of Eternityを囲む土地は、Wild Kingの信奉者たちであふれている。かつては同じ誓いで結ばれ、我らの隣に立っていた者も多い。だがその献身は、無謀な熱狂へと腐ってしまった。奴らは、Nordrassilの世話をしWellを守ろうとする我らの働きを、積極的に妨げている。\n\nこれがたやすいとは言わないし、この手が汚れずに済むとも言わない。それでも、大きな侵攻が始まったときに、奴らが我らの地を傷つけたり、側面を突いたりするのを許すわけにはいかない。\n\n速やかに奴らの数を減らしてくれ。そして、やむを得ぬことをEluneが許してくださるように。", nil, nil, 0x1e74d135, 0x5943acb3, 0x4f3f4838, nil, nil, "...mm" },
  [93585] = { "私のこの光", "Father TuttleをThe Harborageまで護衛する。", "ああ、よかった、まともな方がいらっしゃった！\n\n私はChurch of the Holy Lightの使いとして、Harborageのdraeneiと接触するためにここへ来ました。ご存じのとおり、Allianceはここに足がかりを持っていません。地元の人々と少し外交をすれば、その点で助けになるかもしれないのです。何といっても、光はすべての者を受け入れるのですから！\n\nですが、この橋の先の道は、draeneiのもっと野蛮な同族でいっぱいです。無事にHarborageへたどり着くには護衛が必要です。手を貸していただけますか、{class}？", nil, nil, 0xc51f3c34, 0x6d345a6d, 0xd75f821d, nil, nil, "...mm" },
  [93594] = { "森の言葉", "DesolaceのShen'dralasにあるForlorn GardensでWoodwyrdを見つける。", "首飾りから生まれたトレントのうち、とりわけ一体が、命と知性という贈り物を授かった他の誰よりも抜きん出ていました。もしトレントたちが倒れてしまったのなら、残っているのは彼だけかもしれません。\n\n彼は日中、花の一つ一つ、つぼみの一つ一つの世話をして過ごし、夜は地面に根を下ろして、小さな生き物たちの巣になっていました。\n\nもし彼が生きているなら……そうであるよう祈っていますが……何が起きたのか知っているかもしれません。\n\n私は大切な友、Woodwyrdに望みを託しているのです。", nil, nil, 0x179df125, 0xb62417d2, 0x0360f0cc, nil, nil, "...mm" },
  [93601] = { "責任のなすりつけ", "Bristleback Retreatで重要なquilboarを探し出す。", "あの女の贈り物を取り戻したいなら、北へ進んでValley of Bonesへ入れ。\n\nそれは盗まれた。quilboarのせいだ。我は見た。この二つの目玉でな。\n\nこの庭が枯れ果てる運命にあるのは、奴らのせいだ。\n\n奴らを許すな。", nil, nil, 0x20728ba5, 0x618550b3, 0xf961c073, nil, nil, "...mm" },
  [93604] = { "Agamagganの血", "Razorfen Downsへ向かってVirulent Blood of Agamagganを手に入れ、DesolaceのBristleback RetreatにいるKog'thug the Braveのもとへ持ち帰る。Razorfen Kraulの中にあるBlood of Agamagganでは足りないと、Kog'thugは念を押していた。", "でかい{race}、Razorfen Downsのこと聞いたことある？<フガッ> もちろんない！Barrensのでかい場所。トゲいっぱい。見逃さない。\n\nAgamagganそこで死んだ。quilboarみんなにとって大事な場所。今、bristleback入れない。鼻すすりのRazorfenのもの。Razorfen、quilboarの歴史を敬わない！\n\nAgamagganの血が谷を養う。トゲ育つ。でっかいの。ちっぽけなエルフの首飾りよりでっかい！\n\nDownsへ行け。Kog'thugに血を持ってこい。kraulの古い血はだめ。いい血がいる！\n\n血渡す、首飾りもらう、勝ち。", nil, nil, 0x1163fcf2, 0x0cfaf819, 0xf9fc90a3, nil, nil, "...mm" },
  [93606] = { "鳴き声を交わす仲ではない", "QuolgaにBenevolent BouquetとVirulent Blood of Agamagganを届けて、quilboarの争いを鎮める。Benevolent Bouquetに使う花は、DesolaceのShen'dralas近くにあるForlorn Gardensで手に入る。", "Quolga the WiseはKog'thugの連れ合い。Quolga、すごいトゲ編み。だからKog'thug、Quolga好き。Quolga、でかい{race}が探してる首飾りも持ってる。\n\n問題？おれたち、口きく仲じゃない。そもそもおれたちが首飾り盗んだから、Quolga怒ってる。じゃあなんで使う？Kog'thug、それ知りたい！\n\nでも！Quolga、トゲと同じくらい花も好き。花どこで手に入るか知ってる？首飾り手に入れたところ！\n\nでかい{race}がKog'thugのために花とこの血を持っていけば、Quolga、Kog'thugに怒らないかも？首飾り、交換してくれるかも！\n\nKog'thugごめんって伝えて。", nil, nil, 0x0ea5db95, 0x04b7b218, 0xf669cb01, nil, nil, "...mm" },
  [93609] = { "Forlorn Necklace", "Forlorn NecklaceをDesolaceにあるShen'dralasの神殿のMitheraのもとへ持っていく。", "<探し求めていたnecklaceがついに手に入った。だが残念なことに、中に込められていた魔力はすっかり尽きている。今の状況には好ましくないが、少なくともそのおかげで、quilboarから比較的たやすく手に入れることができた。\n\nこれはMitheraのもとへ持ち帰るのが一番だろう。>", nil, nil, 0xa5264068, 0x94f74381, 0x1aa1f2f8, nil, nil, "...mm" },
  [93615] = { "子猫と親猫", "Mount Hyjalの荒野でShalla'kalの子猫たちを見つける。", "おお、うまそうな一口よ……\n\n恐れるな、戯れだ。もっとも、そなたの背骨など枯れ枝のようにへし折れるがな。何しろ我は荒野の半神なのだから。\n\n我の好意を得て、我の食欲を逃れたいのなら、ひとつ務めを負ってもらおうか？\n\n我が子らが、遊びに出かけてしまった。この山であの子らを直接脅かせるものなどほとんどないが、頂上の近くでは邪悪なものがうごめいておる。何事も運任せにはしたくない。\n\nあの子らの様子を見てきてくれるか？もちろん、そなたを食わずにおいてやる代わりにな。", nil, nil, 0x6bc4255b, 0x8a6d99b7, 0x1ca59bb3, nil, nil, "...mm" },
  [93617] = { "獲物と捕食者", "雄鹿たちが捕食者のように振る舞うのをやめさせる。", "Wild Godsの序列はねじ曲げられた。今やすべてが動き出し、世界の摂理は粘土のように自在に形を変える！\n\nもはや我が同胞が捕食者の牙に苦しむことはない。今こそ、我らを食らってきたすべての者を、我らが食らうのだ！\n\n震えるがいい、か弱き生き物よ。お前には我らを止める力も速さもないのだから！", nil, nil, 0x81831bf9, 0x46431856, 0xc7a3e625, nil, nil, "...mm" },
  [93644] = { "Tattered Journal", "文面から察するに、この日誌の書き手はShen'dralasのどこかにいるようだ。", "<Shen'dralasの近くで見つかったこの汚れた古い書物には、もはや知識のほとんどが残っていない。\n\n残された文章では、一つ一つの文字と単語の区別もつきにくい。最初は読むのに苦労しそうだが、そのうちの一つは姓のようだ。\n\nもしかすると、その著者である「Evenshade」が近くで見つかるかもしれない。>", nil, nil, 0x20929582, 0xcdf8420d, 0x2116d4ce, nil, nil, "...mm" },
  [93663] = { "輸送中の紛失", "行方不明の運び屋を見つけ、Darの積み荷が確実にHarborageへ届くようにする。", "Harborageのdraeneiは腕のいい釣り人で、私よりも危険な海域で網を引くことも厭わない。私たちは時々取引をしている。彼らは獲物の一部をくれて、私は余った物資を少し渡すんだ。\n\n最近の積荷を届けるためにゴブリンの運び屋を送ったんだが、彼は戻ってこなかった。おそらくcrocoliskの餌食になったんだろう。\n\nそれより大事なのは、私の商売の評判がかかっていることだ。あの積荷を見つけて、Harborageへ届けなければならない。頼む、できるなら見つけてくれ。道沿いの水辺の近くを調べてみてくれ。", nil, nil, 0x6d5f7446, 0x57be44a4, 0xbeef4b7a, nil, nil, "...mm" },
  [93678] = { "Draenethystに関する要約メモ", "Azoreが書き写したメモを、Swamp of SorrowsのHarborageにいるMagtoorのところへ持ち帰る。", "Gimashiのdraenethystに関する覚え書きを書き写しておきました。欠片にもある程度の力が宿っているようですが、純粋な球体となれば比べものにならないほど強力です。Burning Bladeが狙っていたのはそれのようですね。\n\nGimashiの覚え書きの多くは、ポータルや悪魔の召喚儀式を暗に示しています。どこへ通じるポータルなのか、どの悪魔を召喚するためなのか、確かなことは言えません。\n\n私の答えは決定的なものではありませんが、この覚え書きを沼地へ持ち帰ってください。私がご一緒しなくても、分かっていただけるとありがたいのですが。", nil, nil, 0x0ea3f6c6, 0x72a9cecd, 0x9a334fa2, nil, nil, "...mm" },
  [93679] = { "別の者の幻視", "MagtoorとともにOnkuの幻視を見る。", "また会えてうれしいです、{name}。あなたが持ってきてくれた記録を読み、私たちの最長老の予見者Onkuとその件について話していました。\n\n彼は最近、draenethystの球へと私たちを導くかもしれない幻視を授かったのです。少しの間ご一緒いただけるなら、その幻視が示したことをあなたにもお伝えしたいのですが。", nil, nil, 0x1fe9b9d1, 0x36a61bce, 0x7c4cafbe, nil, nil, "...mm" },
  [93680] = { "Key to the City", "Tarren MillのMagus Wordeen VoidglareのためにDalaran Sewer Keyを手に入れる。", "AllianceにはKirin Torと呼ばれるメイジの軍団があった。奴らは強大だったが、悪魔のBurning Legionはそれ以上だった。大悪魔Archimondeは一撃のもとに、子供のおもちゃのように奴らの都市を叩き潰した。生き残った者たちは、ただの家なき放浪者に成り下がった。\n\n奴らがDalaranを再建するまではな。しかもDark Ladyのまさに玄関先にだ！\n\n奴らの野営地にいる間に、我々が気づかれずに都市へ入れるものを探してくれ。もっと知らねばならん。", nil, nil, 0xc31a2dd3, 0xa0350c6f, 0xab6858c6, nil, nil, "...mm" },
  [93684] = { "見いだされし者", "Blasted Landsでdraenethystを探しているdraeneiを見つける。", "私たちのような集落はほかに知りませんが、ここから南のBlasted Landsで迷える者たちを見たことがあります。彼らはFallow Sanctuaryの者たちとよく似ていて、敵意に満ち、心を失っていました。あそこにいる同胞は皆、そんな運命をたどったのだと思っていました。\n\nですが、Onkuの幻視が荒れ地をさまよう一人のdraeneiを示しているのなら、私は間違っていたのかもしれません。\n\nもう一度あなたにお願いします、{name}。そのdraeneiを見つけ、できる限り助けてあげてください。", nil, nil, 0xe7198613, 0x26b199a5, 0x03963cc4, nil, nil, "...mm" },
  [93685] = { "Kum'ishaに仕える", "Blasted LandsでFlawless Draenethyst Sphereを見つけ、Kum'isha the Collectorのもとへ持っていく。\n\n注意すること。この宝石はAzeroth全土でも最も希少な水晶の一つだ。この地のどの生き物がFlawless Draenethyst Sphereを持っていてもおかしくない。", "お前のちっぽけな脳みそで、flawless sphere of draenethystの希少さが理解できるか、{race}？draeneiはこの結晶をたった一つ求めて生涯を費やし、目的を果たせぬまま恐ろしい運命をたどってきたのだ。\n\nそれでもお前はKum'ishaの前に立ち、Kum'ishaが何を求めたかを知った上で、なお手を貸したいというのか？よかろう、{race}……この地を旅する間にいつでも、flawless sphere of draenethystを見つけたら、私のもとへ持ってこい。お前の想像をはるかに超える富で報いてやろう。", nil, nil, 0x81cce1f7, 0x6982530b, 0x09d08d4a, nil, nil, "...mm" },
  [93686] = { "Kum'ishaの試み", "Flawless Draenethyst Sphereを見つけ、Kum'isha the Collectorのもとへ届ける。", "裂け目は一部しか成功しなかったが、Kum'ishaは試みを続けねばならない。\n\nDraeneiの希望は、お前の安物への欲と同じくらい熱いのだ、{race}。この呪われた地へもう一度出ていき、flawless draenethyst sphereをもう一つ取り戻してこい。\n\nもちろん、この仕事を引き受けるかどうかは、すべてお前次第だ *ニヤリ*。", nil, nil, 0x25629eb7, 0x0760f0e7, 0x0d0d9783, nil, nil, "...mm" },
  [93689] = { "Kirin Torの友", "City of DalaranのArchmage Celindraと話してください。", "これは素晴らしい知らせです！Dalaranに平和が戻った今、Kirin Torがあなたを両手を広げて歓迎しない理由などありません！\r\n\nどうか、急いで評議会に報告してください。きっと皆、街の救い主に会えるのを楽しみにしているはずです。", nil, nil, 0xa01b2371, 0x8dfa9ac1, 0x71e69736, nil, nil, "...mm" },
  [93735] = { "壊れた構築体", "Valanaarの西側でRiaani Nightwindを見つけてください。", "歴史的に、Windshapersは風の精霊から授けられた魔法の器具や装置の手入れを担ってきました。島中にある無数の魔法の構造体もそうです。精霊たちが去って以来、そのうちまだ動くのはごくわずかです。\n\nValanaarでまだ動く数少ない構造体の一つが損傷してしまいました。職人の一人を助けに向かわせましたが、彼には手助けが必要かもしれません。街の西の端へ行き、できる限りの援助をしてください。", nil, "<Riaaniは機械の重い装甲板の下に顔を突っ込み、その下の仕掛けをいじろうとしている。あなたがいることにはまったく気づいていない。>\n\n嵐に呪われろ、コアはどこだ？！Gyrozephyrまで外そうなんて、誰が考えたんだ？この機械の風がまだ完全に消えていないのは奇跡だぞ！", 0x3b580ff6, 0xb230d6e2, 0x9c9b9f2d, nil, 0xd94b28e4, "...m." },
  [93736] = { "招かれざる霊", "Shadowgale ForestのWind Hollowsから、Wind Hollow Essencesを10個集めてください。", "Windshapersの最大の関心事は、精霊たちがなぜ我々のもとを去ったのか、そして彼らを連れ戻すために何ができるのかを、よりよく理解することです。北のShadowgale Forestの奇妙な特徴の一つに、「hollows」と呼ばれる不思議な風の精がいることがあります。彼らについても、なぜそこにいるのかについてもほとんど分かっていませんが、風の精霊が去った後に初めて現れ始めたことは分かっています。\n\nそこへ行き、彼らを散らしてください。その残骸を集めて、ここへ持ってきてください。", "Shadowgale Forestは危険な場所だ。幽霊が出ると言う者さえいる。私はそんなことは信じていないつもりだが、気の弱い者や備えのない者が行く場所ではないのは確かだ。", "このエッセンスを扱っていると……深い不安に襲われます。悪意に満ちた、悔恨のオーラがそこから漂ってくるのを感じるほどです。気が遠くなりそうです。\n\n<Endariaはかすかに身震いする。>\n\nこれ以上調べるのは気が進みません。", 0x4f4a02b2, 0x24071ed5, 0x120ac132, 0x5f247307, 0x64b49c6f, "....." },
  [93737] = { "壊れた構築体", "Riaani Nightwindと話し、彼の話を聞いて下さい。", "ああ、どうも。Ayessaが手伝いによこしたって？ それならいいか。\n\n君みたいな見るからに素人に何ができるか分からないが、この構造体の中身から頭を引っこ抜くまで少し待ってくれれば、手伝ってもらえそうなことをいくつか思いつくかもしれない。", "この構造物から、なぜわざわざこの部品を盗もうとする者がいるのか想像もつかない。gyrozephyr以外では、これらの部品に実用的な使い道はほとんどない。そのgyroでさえ、本来の目的以外ではほとんど役に立たないだろう。", "材料を集めてきてくれてありがとう。中には手に入れるのがかなり大変な物もあっただろう。\n\nこの部品があれば、あの機械をまた動かせる。あとは記憶が無事で、誰が部品を持ち去ったのかを教えてくれることを願うだけだ。", 0x3b580ff6, 0x20bf5d1d, 0xc9fcddd9, 0x57705db0, 0xf88bb130, "....." },
  [93738] = { "壊れた構築体", "ValanaarのAyessa Dawnsingerのところへ戻って報告してください。", "Brightwishだと？つまりHigh Orderは、何らかの理由でこれらの部品を取り除きたかったわけか。だが、いったいなぜだ？\n\nHigh Orderは昔から干渉好きで、いつも風の精霊の魔法で実験をしたがっている。奴らは度を越して大胆で、Windshaperの管轄にある知識に手を出すことは固く禁じてきたのだが、最近は我々の忍耐を試すようなことばかりしている。\n\n分かったことをAyessa Dawnsingerに報告するといい。この先どうすべきか、彼女が指示してくれるだろう。", nil, "実に興味深い。では、機械が壊れたのはHigh Orderのせいだったと？\n\nBelathaanのことは知っている。Valennia Stormfistのいとこで、実は母親はWindshaperだった。彼がこれに関わっていたとは残念だ。\n\n少し考えさせてくれ。", 0x3b580ff6, 0x29d7b548, 0x98b46a4e, nil, 0xe4724d1e, "...m." },
  [93739] = { "Hordeを探る", "Grommash HoldのNazgrelと話し、さらなる指示を受けてください。受けた指示に従って、Vol'jin、Cairne Bloodhoof、Lady Sylvanas Windrunnerを探し出して話してください。", "Azerothは広大な世界で、Hordeの領土も広い。Undercity、Orgrimmar、Thunder Bluffには、それぞれまったく独特な民と文化がある。\n\nここAzerothでHordeの客人となるのなら、我らの首都を順に一つずつ訪ねておくとよいだろう。道順は私の相談役のNazgrelに聞くがいい。", nil, "戻ってきたのですね。旅で多くを学べたことを願っています。\n\n私の知る限り、あなたの同胞はまだMulgoreで足場を固めているところです。彼らを待つ間、Orgrimmar周辺の地を探索してみてはどうでしょう。特にBarrensは、あなたのような意欲ある冒険者をいつでも必要としています。", 0x7968676a, 0x9721d08e, 0xc1326b85, nil, 0x9b3fc549, "...m." },
  [93740] = { "血には血を", "Gustberry LowlandsのAl'Akethの信者の死体から、Al'Aketh Windstone Charmsを10個集めてください。", "今朝、Windshaperの見習いたちが何人もHighlandsで死んでいるのが見つかった。確かなことは言えないが、Al'Akethの仕業である可能性が高い。Windshapersは、血には血で報いる。必ずだ。\n\n北へ向かい、出会ったAl'Akethを片っ端から倒せ。その証として、奴らのwindstone prayer charmsを持ってこい。我々は許さないし、忘れない。", "Al'Akethはあまりにも長く血塗られた狂信を続けてきた。これは奴らが受ける報いの始まりにすぎない。", "<風の石のお守りを手渡すと、Ayessaは動揺し、どこか上の空の様子だ。>\n\n私のことは気にしないで、{name}。今日はただ……つらい一日だったというだけです。これまでのwindshapersへの尽力に感謝します。", 0x8fdc4a0a, 0xc45880fd, 0xe1adb7e7, 0xe653122a, 0x7adc4448, "....." },
  [93746] = { "断固たる対応", "Shrine of Akirへ向かう道沿いでBelathaan Brightwishと対決して下さい。", "High Orderには、Windshaperの問題に首を突っ込めばどうなるか警告してある。Belathaanを見せしめにして、いくつか痣をつけて、我々の定めた境界への健全な敬意を植え付けたうえでHigh Orderへ送り返すべきだと思う。\n\nBelathaanは町を出て、北のShrine of Akirへ向かうところを見られている。なぜそこへ向かったのかは分からないが、道中で一人のところを問い詰めるのが最も安全だ。彼を見つけて、心に少し恐怖を植え付けてやれ。", nil, "待って、何ですって？！Belathaanが……死んだ？\n\n<起きたことを話すと、Ayessaは耳を傾ける。>\n\nHigh OrderがAl'Akethと会って和平を話し合っていた？教団との和平などありえません。彼らは人殺しの狂信者です。Belathaanを一人で交渉に行かせるなんて、Elaadrinは何を考えていたのでしょう？\n\n気にしないで、{name}。これはあなたのせいではありません。またしても、High Orderの傲慢さが悪いのです。あなたはただ、正しい場所に間の悪い時に居合わせただけです。", 0x2e10a415, 0x87bb368c, 0x049e9393, nil, 0x348cc12c, "...m." },
  [93747] = { "暴力を緑へ", "Ruined Ballista、Ruined Catapult、Ruined Flying Machineの近くにEnchanted Seedsを植える。", "戦争の古い残骸は朽ちてさびついていますが、自然に還る流れを早めることはできます。\n\n以前あなたが集めてくれた種の入ったこの袋を持っていってください。成長を早めるために、少し魔法をかけておきました。古い戦争の機械の近くに置いて、それを覆うように育たせてください。戦争の記憶は過去へと薄れ、自然が自らの場所を取り戻すでしょう。", nil, nil, 0xc53cebe8, 0x7e1203ac, 0xe11a4e9b, nil, nil, "...mm" },
  [93759] = { "自然の恵み", "隠者のシチューのために、汚れていないHyjal StagsからHyjal Venison Cutsを$N1個、Scarlet Dart Tubersを$N2個集める。", "よくやってくれました。私も、この山も、あなたに大いに助けられました。\n\nちょうどシチューを作っているところなので、材料集めを手伝ってくれるなら、喜んで分けてあげますよ。\n\n野生の動物を殺すのは気が進みませんが、命の循環には糧が必要です。材料の釣り合いが取れていれば、きっとおいしくなります。Hyjal StagsからとったHyjal Venison Cutsを少しと、近くの緑の多い場所に育つScarlet Dart Tuberのでんぷん質の根を合わせると、よく合うはずです。", nil, nil, 0x5beaeffa, 0x1f0892b4, 0xf15ee8f2, nil, nil, "...mm" },
  [93773] = { "盟約", "Mount HyjalのKetharasのもとへ報告に戻る。", "Ve'hanは、少なくともWild Godの力の一部を盗むことに成功したようです。そんなことは私には信じがたいのですが、現にこうなっています。\n\nそれに、Ve'hanが口にしたあの「Pact」とは何なのでしょう？{name}、Ketharasのもとへ戻らねばなりません。わかったことを彼に伝えてください。\n\n申し上げにくいのですが、Ve'hanのような敵を倒すのは、おそらくあなたの力をはるかに超えています。この魔法に対抗できるのは……そう、Wild Godsご自身の力だけかもしれません。", nil, nil, 0x119207ff, 0xed7ba21f, 0x00ac7e53, nil, nil, "...mm" },
  [93786] = { "血で書かれた伝言", "Meadowsbrook Farmhandを$N1体倒し、成功の知らせを持ってKrom'roshのところへ戻る。", "お前の刃は人間の血に飢えているか、{name}？\n\n数年前、人間の離反者どもが川を渡った南西の小さな農場を自分たちのものにした。このあたりは材木と石が豊富だ。奴らが東の岸にあるFarholdeという砦まで手を広げるのは時間の問題だった。\n\n最初の小競り合いも、数さえ揃っていれば我々の勝ちで終わっていただろう。我々がここにいることを奴らに思い出させる時だ。\n\n奴らの農作業を妨害しろ。捕虜は取るな。はっきりとした警告を送ってやれ。", nil, nil, 0x356cfc07, 0x5be31a62, 0x997a25a0, nil, nil, "...mm" },
  [93787] = { "取り放題の食料", "MeadowsbrookにあるAllianceの農場からFeed Satchelを$N1個盗み、Krom'roshのところへ戻る。", "この地の人間どもは、この地がもたらす温もりと安らぎと糧を長く享受してきた。そろそろ奴らからそうした快適さを奪ってやる時だ。\n\n南西の農場で敵の物資を探し出せ。見つけた物は何でも奪ってこい。\n\n刃を血に染めるほどの愉しみはないだろうが、奴らの足を遅らせれば、次の一手を練る時間が稼げる。", nil, nil, 0x92341ffc, 0xa56852d0, 0x5a1cd66b, nil, nil, "...mm" },
  [93788] = { "借り物の刃", "Rog'marにいるKreza Darkthornのために、Turner's Logging Campの木こりたちからWoodworker's Axeを$N1本取り戻す。", "南には人間、西にはTwilightがいて、資源の奪い合いは厳しくなっている。だが、敵の刃で事足りるのに、なぜ敵のただ中で資源を集める必要がある？\n\n川沿いに南へ下って製材所へ行け。木々の間から木こりたちの口笛が聞こえたら、足音を忍ばせろ。好機が来たら、強く素早く叩け。\n\n俺はここに残って炉の火を絶やさずにおく。Gur'dokが奴らの刃を潰し、俺がその材料で武器を鍛え直す。", nil, nil, 0x4c24b02a, 0x30e0c2f0, 0x82fe6d0e, nil, nil, "...mm" },
  [93791] = { "Belannとの対話", "ValanaarのBelann Windwoodと話してください。", "{name}、あなたの魔法の腕が上がっているのは明らかです。若く志あるメイジのための、High Orderの最も古い伝統の一つに参加する時が来たと思います。あなた自身の呪文の触媒を作る時です。\n\nValanaarのBelann Windwoodを訪ねてください。彼は一世紀以上もHigh Orderのために杖やワンドを作ってきましたから、安心して任せられます。", nil, "ああ、あなたが{name}ですね？我々のしきたりと歴史を熱心に学ぼうとする若いメイジを見ると、心強く思います。さあ、あなたの呪文の焦点具を作る次の手順を説明しましょう。", 0x9eee1307, 0xdac9b99f, 0x9e12128a, nil, 0x293bd11b, "...m." },
  [93797] = { "風に揺れる枝", "Wind-Infused BoughをValanaarのBelann Windwoodに届けてください。", "ある程度の魔法の熟練を示した若いメイジが、自分自身の呪文の触媒を作るのは、昔ながらの伝統だ。これは普通、我らの最も古い木々から落ちた枝を集めて行う。そうした木々には風の元素の痕跡がわずかに残っているからね。\n\n最も理想的な枝は、Falaath Villageのすぐ南にある風の祠の近くにあると分かった。行って大きな枝を持ってきてくれれば、君の呪文の触媒を作りながら伝統について教えよう。", "Zephrasでは年を追うごとに、魔法の才に恵まれた者がどんどん少なくなっています。\n\nあなたのような若いメイジが、私たちの最も古い伝統に加わり、歴史と文化を守り続ける手助けをしてくれるのを見られて嬉しく思います。", "ありがとう、{name}。この大枝には、才能ある者に使いこなされるのを待つ元素の力が確かに感じられます。素晴らしい呪文の焦点具になるでしょう。\n\nもしかして、この枝があなたに歌いかけてきましたか？枝が{class}を選ぶのであって、その逆ではない、ということはよくあるのです。\n\n<Belannはくすくす笑いながら、あなたの手からそっと大枝を受け取る。>", 0x53b7cabb, 0xbb3c4f26, 0x55b3e7d7, 0xf0384662, 0x12ab22f5, "....." },
  [93825] = { "Barkboundの祝福", "Moonveil Mossの塊を$N1個集めて、Suma Mossmaneのもとへ戻る。", "我らから学びたいのか？Hyjalの木々は我らに語りかける。その樹皮には命が宿り、その上に我らがMoonveilと呼ぶ苔が育つ。柔らかく、緑で、山の魂を宿して力強い。傷を癒やし、根を祝福するために、我らにはこの苔が必要だ。\n\n行け、優しき者よ。霧がまとわりつき、日の隠れる古い木々を探せ。その樹皮からMoonveil mossを取り、私のもとへ持ち帰ってくれ。それがあれば、我らを苦しめるものを癒やせる。", nil, nil, 0x5c92c768, 0x3a31960e, 0xc8dcf0cc, nil, nil, "...mm" },
  [93826] = { "Deadwoodに恐怖を", "Deadwood Totemicsを$N1体とDeadwood Fel-Tendersを$N2体倒し、Elder Pinespeakerのもとへ戻る。", "古き習わしはDeadwoodから失われた。奴らの爪は木を引き裂き、その心は怒りに燃えている。奴らは我らを襲い、野は揺れる。\n\nfurbolgの友よ、お前なら助けになれる。奴らの巣へ行け。野生は欲に屈しないと見せてやれ。根を汚す者どもを討ち、その叫びが木々から消えたら戻ってこい。賢くも哀れな奴らの賢者どもに終わりをもたらせ。奴らはフェルと汚れた蔓をねじ曲げている。\n\nこれを成し遂げれば、我らは精霊たちにお前の名を語ろう。", nil, nil, 0xb297c2ea, 0xd54d0578, 0x9bf77e21, nil, nil, "...mm" },
  [93827] = { "風に晒された護符", "Enchanted Harpy Amuletを$N1個集めて、Thobon Sapclawのもとへ戻る。", "山の風が不吉な兆しを運んでくる。Harpiesは我らの足の届かない高みに巣を作る。奴らが身につける宝石には強い力が宿っている。我らのまじないと結べば、呪いから我らを守り、精霊を我らの結界に縛りつける。\n\nだが登るのは険しく、harpiesは爪と嵐で襲ってくる。噂どおりお前が強いなら、風が叫ぶ高い岩山へ行け。Harpyの住処はHyjalの中ほど、北東にある。我らの頭上を飛ぶのが見える。空の魔女どもからまじないを奪い、私のもとへ持ってこい。", nil, nil, 0x0ac14840, 0x4d08bc3a, 0xa5321dcf, nil, nil, "...mm" },
  [93828] = { "窪地の薬草", "Barkskin Burrowの周辺からDried Hanging Herbsを$N1個集めて、Fennar Mossmaneのもとへ持ち帰る。", "この泉のそばでは山の息吹が湿っていて、この重い空気では私の薬草が乾かない。我らの仲間は野から戻ると、根が風通しを許すところならどこでも荷を吊るす。巣のあちこちにな。\n\nさあ行け。我らの住処のまわりに吊るされた乾いた薬草の束を見つけ、私のもとへ持ってこい。それで、我らの魂を強く保つ包みと守りを編もう。", nil, nil, 0x77ca1fc6, 0x154b0313, 0x1c3f1aa6, nil, nil, "...mm" },
  [93830] = { "Hyjalの水", "Fennar Mossmaneから渡された水袋を、Deadwood Furbolgの巣穴の外にある池で満たす。", "DeadwoodはMount Hyjalの雪解け水から生まれた池のそばに住んでいる。その水は清らかで、山の息吹を宿して力強い。我らはそれを薬に使い、根を死から救う。\n\nここでは泉の流れが遅い。我らの水源は守らねばならず、大切に使わねばならない。だが奴らの池は命に満ちて流れ、我らの巣を二度満たせるほどだ。友よ、その水を満たした革袋を私に持ってきてくれ。精霊がお前の歩みを祝福し、我らの巣は山の恵みを深く飲むだろう。", nil, nil, 0x62b45624, 0x99749f05, 0xb35febbe, nil, nil, "...mm" },
  [93831] = { "Sweetpaw Jam", "HyjalでBear Berriesを$N1個集めて、Osi Mistpawのもとへ戻る。", "山の風みたいな匂いがするね、強くて自由だ！手がふさがってないなら、頼みたいことがあるんだ。\n\n僕らはbear berriesが大好きでね、丸くて赤くて、霜のあとの蜂蜜みたいに甘いんだ。木陰のあたりを探してごらん。とがった岩と狂った翼が多すぎて、僕らじゃ一番熟した茂みに手が届かないんだよ。\n\nひと房持ってきてくれたら、Sweetpaw Jamを作るよ！僕のとっておきのごちそうさ、味見させてあげる。\n\nどうだい？", nil, nil, 0xd1ab83fa, 0x6260d4c2, 0x362cb3cc, nil, nil, "...mm" },
  [93832] = { "Stonewatchersの粉砕", "Hyjal上部の破壊されたAllianceの基地でEternal Sentryのガーゴイルを$N1体破壊し、Elder Mistpawのもとへ戻る。", "高い斜面に石の翼がいる。岩の獣だ。半分生きて、半分死んでいる。汚れた手が奴らを彫る。じっとした姿を信じるな。その目は一歩の踏み間違いを待っている。\n\n我らの子らはその危険を知らない。一歩近づきすぎれば、石は爪と牙で目を覚ます。\n\n行け、この呪われた像を打ち砕け。翼を折り、欠片を砕き、山が自由に息をできるようにしてくれ。", nil, nil, 0x8a1f7728, 0xd4ca3a87, 0xe2c1ee12, nil, nil, "...mm" },
  [93833] = { "邪悪な知恵", "フクロウの死骸を$N1体、HyjalのBarkskin BurrowにいるElder Pinespeakerのもとへ持っていく。", "Hyjalの梟は羽と飛ぶ姿だけのものではない。その爪も、羽根も、骨でさえも野生をささやく。我らはこの贈り物を使って護符を作る。精霊を結びつけ、仲間を守るまじないだ。\n\nだが梟は進んで差し出してはくれない。山が差し出すものを、お前が取らねばならない。梟を$N1羽仕留め、その亡骸を私のもとへ持ってこい。\n\nそうだ、体を丸ごと持ち帰ってほしい。あれほど優美な生き物が与えてくれるものを、我らは何ひとつ無駄にしないのだ。", nil, nil, 0xb4d1a9ff, 0x4a3e9b6b, 0xb03a5a16, nil, nil, "...mm" },
  [93834] = { "穴掘り甲虫", "Dala FairmawのためにBurrow Beetle Bitsを$N1個集める。", "穴掘り甲虫だ！まったく厄介者で……今じゃ自分の巣よりも我らの巣を掘っている。こそこそ通るのを見かけたら叩き返して棍棒を振るうが、奴らはすばしっこくて、暗闇に隠れるのが奴らの盾なんだ。\n\n我らの巣を登るときに見かけたら、潰してくれ！潰れた殻はもらって食事にする。だから悪いことばかりじゃないさ。", nil, nil, 0xaed0eb27, 0x34fe3623, 0xdd4a4bfd, nil, nil, "...mm" },
  [93835] = { "Lorthunaとの対決", "頭上のRohashi Spiresへ通じるポータルを使い、High Priestess Lorthunaと対峙するElaadrin EvengaleとAyessa Dawnsingerに加わってください。", "Lorthunaは何かのポータルを使って上の尖塔へ逃げた。AyessaとElaadrinが後を追って入っていった。ほんの少し前のことだ。\n\nすまないが、攻撃を1発多く食らいすぎた。私はここまでだ。ポータルを抜けて、Elaadrinを見つけ、彼らがLorthunaを止めるのを手伝ってくれ。\n\nElaadrinとAyessaが呼んだという援軍がすぐに来ない限り、ここからは君一人だ。幸運を、{class}。", "残念だが、我々の状況はこれでいっそう絶望的になってしまったようだ。", "Valenniaと部隊も無事に逃げられるよう、残っているメイジを何人か送りました。彼女は今、High Elder Shadowsongの住まいで休んでいるはずです。\n\nAnsiremはAzerothへ戻らねばなりませんでしたが、発つ前にHigh Orderの次の手立てについて彼と話し合いました。今日は生き延びましたが、Zephrasは今、危険なほど無防備です。これから来るものに備えて計画を立てねばなりません。", 0x90290d9d, 0x21f66bcc, 0xcf4192f2, 0x2b65e1b1, 0x2047cb19, "....." },
  [93836] = { "Zephrasの運命", "ValanaarのTalaanis Shadowsongと話してください。", "Mulnはエレメンタルの王たちについて多くを語ってくれたが、我々にはAl'Akirを恐れるだけの十分な理由があるようだ。Zephrasを彼の目から隠していた結界が消えた今、我々はまったくの無防備だ。彼が攻撃してくると決めたなら、彼自身の領域であるここでは、我々に勝ち目はない。\n\nHigh Elder Shadowsongは、我々が置かれている危険と、何より、Azerothへの任務における我々の意図を知る必要がある。我々は故郷を救う手立てを見つけ出す。誓おう。", nil, "<Shrine of Akirの上で起きたこと、そしてZephras Isleを去るというAyessaの計画を話すと、Talaanis Shadowsongはじっと耳を傾ける。>\n\nさらに考えねばならぬが、良い面を見れば、我らはLorthunaを退け、教団から指導者を奪った。我らの故郷はまだ侵されてはおらぬ。元素の神々の時の流れからすれば、Al'Akirが我らに目を向けるまでには何年も……いや、何十年もかかるやもしれぬ。\n\n今は恐れるべきことも多いが、祝うべきことも多いのだ。", 0x6d3ea2fe, 0x4440ff8a, 0x7c6d6603, nil, 0xa70add28, "...m." },
  [93848] = { "見事な仕事ぶり", "Ketharasのもとへ戻り、Summit of Eternityで起きたことを伝える。", "Ketharasがこの脅威に対抗するために編み出した魔法は、この勝利に欠かせないものだった。我々のドルイドならその魔法を再現し、Blackthorne Pactに力を与えている結界を大規模に解くことができるはずだ。\n\nKetharasのもとへ戻り、ここで何が起きたかを伝えてやってほしい。Guardians of HyjalとCenarion Circleが彼に感謝していると伝えてくれ。再び仲間のドルイドと肩を並べる場所を望むなら、いつでも我々のもとに歓迎されると知っておいてほしい。", nil, nil, 0x250ba072, 0x11111364, 0x3ed9c37b, nil, nil, "...mm" },
  [93862] = { "木箱の返却", nil, nil, nil, nil, 0xeb410c2b, nil, nil, nil, nil, ".mmmm" },
  [93925] = { "Brerufaへのビーズ", nil, nil, nil, nil, 0xcdfc3bdc, nil, nil, nil, nil, ".mmmm" },
  [93926] = { "西の見張り", "西の見張り塔でPeacekeeper Vaanielを見つけてください。", "教団が塔を襲う理由が何であれ、そのために我々の仲間を失う価値はない。\n\n南西へ向かって、あの見張り塔の様子を確かめてきてほしい。そこにいる治安維持隊を見つけて、村へ引き返すよう伝えてくれ。あの塔を守り抜くことは、それで失われる命に見合わない。それよりも、今いる守備兵をここに集めて市民を守りたい。\n\n指揮を執っているのはPeacekeeper Vaanielだ。できるだけ早くここへ戻るよう伝えてくれ。急げ！", nil, "<ここにある遺体はまだ比較的新しく、殺されてからそれほど経っていないのは明らかだ。この治安部隊員の肌に残る火傷と焦げ跡からすると、教団の嵐を操る呪文使いたちに殺されたのは明らかだ。>", 0x18869d4a, 0xc19f2264, 0x3e46d2b0, nil, 0x4daf9d77, "...m." },
  [93927] = { "最後の頼み", "死んだ平和維持官のそばで見つけた書き付けを拾い、それを読んで次にすべきことを決めてください。", "<死んだ治安維持隊員の遺体を調べていると、血に濡れたメモがその手から落ちた。拾って読めば、ここからどうすべきか手がかりが得られるかもしれない。>", "西の見張り所から何か知らせは？", "では、全員死んだのか。教団のくそったれどもに嵐の呪いあれ！\n\nあなたは司祭を倒し、塔の教団員たちを止めてくれたが、正直に言うと、奴らが柱に何かをしていたというあなたの話が、今は二重に気がかりだ。あれほど大量の風の石が奴らのところに蓄えられていたということは、そのために膨大なエネルギーが必要だったということだ。\n\n考えずにはいられない。奴らの最終的な狙いは何だ？柱を冒涜し、村を襲う？何のために？", 0x96fa8046, 0xf1e8b9e6, 0xc18d4d9f, 0x3a64b789, 0xeb80b8f1, "....." },
  [93928] = { "ネズミとミルク", "ネズミにクッキーを取ってきてあげてください。", "クッキーがほしいんだ、分かるか？\n\nへっ！", nil, nil, 0x4a4cc954, 0xaadb1f71, 0xe2b329a9, nil, nil, "...mm" },
  [93948] = { "印章の配達", "Shadowsong Family SignetをValanaarのTalaanis Shadowsongに届けてください。", "どうせValanaarへ行くのなら、塔で取り戻した印章指輪をValanaarのTalaanis Shadowsongに届けてください。\n\n彼はこれを取り戻したいでしょうし、何より、甥の身に何があったのか知りたいはずです。TalaanisはZephras IsleのHigh Elderであり、何より、今の苦難にもかかわらず民に深く愛されている善き人です。この知らせに彼がどう反応するかを思うと胸が痛みます。彼の喪失にお悔やみを伝えてください。", "私に何を持ってきたんだ？ああ……なんてことだ。", "私の……甥が死んだとは、本当に残念です。これを取り戻し、私のもとへ届けてくれたことに心から感謝します。\n\nあなたほど有能な若いshen'doreiが高地から下りてくることはめったにありません。仕事が必要なら、ここValanaarの治安部隊の隊長、Valennia Stormfistと話してください。近頃は、得られる助けはすべて必要なのです。", 0x95398690, 0x57f7b4b1, 0xba89a78d, 0x93229de8, 0x0454cabb, "....." },
  [93949] = { "虫にやられて", "ValanaarでSkyhopperを倒し、Enchanted Skyhopperを$N1体始末する。", "盗聴されていたんだ。\n\n低地は今skyhopperの季節で、つまりそこら中にこの害虫がいる。High Orderのメイジの一人が、倒した虫の一匹に何かの付呪がかけられていたと報告してきた。よく調べてみると、盗み聞きの呪文の一種らしい。\n\n教団がこの付呪された虫を密偵として使っているのではないかと我々は疑っている。行って駆除してきてくれ。見た目ではどれが付呪されているか分からないから、全部倒すしかない。", nil, "Valanaarの周りにはこういう小さな生き物がまだいるに違いないが、魔法をかけられたskyhopperを踏みつぶすたびに、街はほんの少し安全になる。", 0xebc83872, 0xf0db79e8, 0x5a7063fe, nil, 0xf7ae869a, "...m." },
  [93951] = { "ささやかな美", "Shen'dar HighlandsでHippogryph Downの羽根を8枚集めてください。", "村の南西に住み着いたヒッポグリフたちは厄介者になることもありますが、その羽根を手に入れるまたとない機会でもあります。skyborneの多くは鮮やかな羽根で髪を飾るのが大好きで、ヒッポグリフの綿毛はとりわけ鮮やかで、何より絹のように柔らかいのです。\n\nそちらへ向かうなら、巣のまわりに落ちている羽根をできるだけたくさん集めてみてください。野生のヒッポグリフはよそ者に寛容ではないので、どうか気をつけて。", "どんな素敵なものを持ってきてくれたの？", "髪飾りのために羽根を集めるなんて、ちょっとした虚栄の些事に見えるかもしれません。けれど、こんな時だからこそ、小さな喜びをできるだけ大切にする必要があるのです。\n\n私の作った物がひとつでも誰かに喜びをもたらすなら、それは良い一日だったと思えます。これを持ってきてくれて、Zephrasに喜びを届ける手伝いをしてくれてありがとう。", 0xfb24871b, 0xf83626f8, 0x2b37a842, 0x1bd026f8, 0x6c68b48e, "....." },
  [93952] = { "力による均衡", "Deadwood Den Guardiansを$N1体倒し、Brerufaのもとへ戻る。", "Barkskinは弱い根の上に立っている。Deadwoodは我らの地に爪を立て、日ごとにその腐れは深く掘り進み、さらに沈んでいく。我らだけでは持ちこたえられない。\n\nDeadwood Denの衛兵どもが奴らの力の要だ。我らの信頼を求めるなら、森を汚す者どもを打ち倒せ。奴らの守護者が倒れれば、部族の残りも弱まる。そうすれば勝ち目は五分になる。\n\n均衡のために奴らを倒し、Hyjalをひとつに保つ手助けをしてくれ。", nil, nil, 0x40ef28a0, 0x57931f97, 0xa9eeb288, nil, nil, "...mm" },
  [93958] = { "奥の聖域", "Shrine of Akirの内陣にいるValennia Stormfistと話してください。", "Valenniaの部隊がたった今、内なる聖域に突入した。最初は中で激しい戦いになっていたが、今は……不気味なほど静かになった。中へ入って、Valenniaと彼女の部隊に合流できるよう最善を尽くしてくれ……まだ誰か残っていればだが。\n\n私はここに残って、君の背後を守る。", nil, "<Valenniaはひどい傷を負っているようだ。>", 0x757fc20c, 0xb9c9ad7e, 0xfe6de4be, nil, 0x3a2cf55d, "...m." },
  [93963] = { "Allianceを探る", "Stormwind KeepのRandal Emersonと話し、さらなる指示を受けてください。受けた指示に従って、King Magni Bronzebeard、High Tinker Mekkatorque、Tyrande Whisperwindを探し出して話してください。", "Stormwind、Ironforge、Darnassusには、それぞれ独自の民と文化があります。ここAzerothのAllianceの客人として、我々の首都を順に訪ねる時間を取るとよいでしょう。\n\nまずは南の控えの間にいるRandal Emersonに道を聞いてください。", nil, "ああ、戻ったのですね。\n\nあなたの冒険が、この世界の広大さと驚異を感じさせてくれたことを願っています。圧倒されるように思えるでしょうが、同胞を助けるつもりなら、Azerothにいる間に何が降りかかろうと備えておかねばなりません。\n\nあなたの結社がDalaranで足場を固めるのを待つ間、Stormwind周辺の地に目を向けてみてはどうでしょう。特にWestfallは、その気があるなら、力を貸してくれる強い冒険者をいつでも歓迎しています。", 0xb5c2bf15, 0x80cbe7b7, 0x7db457d1, nil, 0xd5e8b7c2, "...m." },
  [93971] = { "Farholde Scouting Report", "報告書をRog'marのKrom'roshのもとへ持っていく。", "<報告書はFarholdeの印章で封をされている。この情報はRog'marのKrom'roshにとって興味深いものかもしれない。>", nil, nil, 0xd11ff624, 0xbf57cd76, 0x1574b004, nil, nil, "...mm" },
  [93976] = { "ゴブリンの商人", "Rog'marの東の波止場にいるKreza Darkthornの知人に刃を届ける。", "Gur'dokと俺が作業を続けている間に、ある友……いや、友というのは言い過ぎか……港にいる知り合いのために、特別な刃を一振り仕上げておいた。こいつは顔が広くて、王国中、いやそれ以上にまで伝手がある。\n\nこれを持っていけ。届けたら、俺の使いだと伝えろ。それから、これで貸し借りなしだと言ってやれ。", nil, nil, 0xee14b2bd, 0xf6d31b37, 0x6e8deb9f, nil, nil, "...mm" },
})
